                </table>
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { Project, Movement, Item, UserRole, MovementType } from '../types';
import { PlusIcon } from './icons/PlusIcon';
import { ArrowLeftIcon } from './icons/ArrowLeftIcon';
import { HardHatIcon } from './icons/HardHatIcon';

interface ProjectsViewProps {
    projects: Project[];
    movements: Movement[];
    items: Item[];
    onAddProject: (project: Omit<Project, 'id'>) => void;
    onGoBack: () => void;
    userRole: UserRole;
}

export const ProjectsView: React.FC<ProjectsViewProps> = ({ projects, movements, items, onAddProject, onGoBack, userRole }) => {
    const [isAdding, setIsAdding] = useState(false);
    const [newProjectName, setNewProjectName] = useState('');
    const [newProjectDesc, setNewProjectDesc] = useState('');
    const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

    const projectStats = useMemo(() => {
        return projects.map(project => {
            const projectMovements = movements.filter(m => m.projectId === project.id && (m.type === MovementType.CHECK_OUT || m.type === MovementType.WASTE));
            const totalItems = projectMovements.reduce((acc, m) => acc + m.quantity, 0);
            const totalCost = projectMovements.reduce((acc, m) => {
                const item = items.find(i => i.id === m.itemId);
                return acc + (item ? item.price * m.quantity : 0);
            }, 0);
            return { ...project, totalItems, totalCost };
        });
    }, [projects, movements, items]);

    const selectedProject = useMemo(() => 
        projectStats.find(p => p.id === selectedProjectId), 
    [projectStats, selectedProjectId]);

    const detailedMovements = useMemo(() => {
        if (!selectedProjectId) return [];
        return movements
            .filter(m => m.projectId === selectedProjectId && (m.type === MovementType.CHECK_OUT || m.type === MovementType.WASTE))
            .map(m => {
                const item = items.find(i => i.id === m.itemId);
                return {
                    ...m,
                    itemName: item?.name || 'Desconocido',
                    price: item?.price || 0,
                    subtotal: (item?.price || 0) * m.quantity
                };
            })
            .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [movements, items, selectedProjectId]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newProjectName.trim()) return;
        onAddProject({ name: newProjectName, description: newProjectDesc, status: 'active' });
        setIsAdding(false);
        setNewProjectName('');
        setNewProjectDesc('');
    };

    if (selectedProject) {
        return (
            <div className="bg-white p-6 rounded-xl shadow-md min-h-full">
                <div className="flex items-center justify-between mb-6 border-b pb-4">
                    <div className="flex items-center">
                        <button onClick={() => setSelectedProjectId(null)} className="mr-4 p-2 rounded-full hover:bg-gray-100">
                            <ArrowLeftIcon className="w-6 h-6 text-gray-600" />
                        </button>
                        <div>
                            <h2 className="text-2xl font-bold text-gray-800 uppercase">{selectedProject.name}</h2>
                            <p className="text-sm text-gray-500">Desglose detallado de materiales y gastos</p>
                        </div>
                    </div>
                    <div className="text-right">
                        <p className="text-xs text-gray-500 uppercase font-bold">Costo Total de Obra</p>
                        <p className="text-3xl font-extrabold text-blue-600">${selectedProject.totalCost.toLocaleString()}</p>
                    </div>
                </div>

                <div className="mb-6 grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="bg-blue-50 p-4 rounded-lg">
                        <span className="text-xs text-blue-700 font-bold uppercase block mb-1">Items Retirados</span>
                        <span className="text-xl font-bold">{selectedProject.totalItems} unidades</span>
                    </div>
                    <div className="bg-gray-50 p-4 rounded-lg col-span-2">
                        <span className="text-xs text-gray-500 font-bold uppercase block mb-1">Descripción</span>
                        <p className="text-gray-700 italic">{selectedProject.description || 'Sin descripción adicional.'}</p>
                    </div>
                </div>

                <div className="overflow-x-auto border rounded-lg">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase">Fecha</th>
                                <th className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase">Material / Insumo</th>
                                <th className="px-4 py-3 text-center text-xs font-bold text-gray-500 uppercase">Cant.</th>
                                <th className="px-4 py-3 text-right text-xs font-bold text-gray-500 uppercase">P. Unitario</th>
                                <th className="px-4 py-3 text-right text-xs font-bold text-gray-500 uppercase">Subtotal</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {detailedMovements.map(m => (
                                <tr key={m.id} className="hover:bg-gray-50">
                                    <td className="px-4 py-3 whitespace-nowrap text-xs text-gray-600">
                                        {new Date(m.timestamp).toLocaleDateString()}
                                    </td>
                                    <td className="px-4 py-3 text-sm font-medium text-gray-900">
                                        {m.itemName}
                                        {m.isLoan && <span className="ml-2 text-[10px] bg-orange-100 text-orange-700 px-1 rounded">PRÉSTAMO</span>}
                                    </td>
                                    <td className="px-4 py-3 text-center text-sm font-bold">{m.quantity}</td>
                                    <td className="px-4 py-3 text-right text-sm text-gray-600">${m.price.toFixed(2)}</td>
                                    <td className="px-4 py-3 text-right text-sm font-bold text-gray-900">${m.subtotal.toFixed(2)}</td>
                                </tr>
                            ))}
                            {detailedMovements.length === 0 && (
                                <tr>
                                    <td colSpan={5} className="text-center py-10 text-gray-400">No se han registrado retiros para esta obra todavía.</td>
                                </tr>
                            )}
                        </tbody>
                        {detailedMovements.length > 0 && (
                            <tfoot className="bg-gray-50">
                                <tr>
                                    <td colSpan={4} className="px-4 py-3 text-right font-bold text-gray-700">TOTAL GASTADO:</td>
                                    <td className="px-4 py-3 text-right font-extrabold text-blue-600 text-lg">${selectedProject.totalCost.toLocaleString()}</td>
                                </tr>
                            </tfoot>
                        )}
                    </table>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-white p-6 rounded-xl shadow-md">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6">
                 <div className="flex items-center mb-4 md:mb-0">
                    <button onClick={onGoBack} className="mr-4 p-2 rounded-full hover:bg-gray-100">
                        <ArrowLeftIcon className="w-6 h-6 text-gray-600" />
                    </button>
                    <div>
                        <h2 className="text-2xl font-semibold text-gray-800 flex items-center">
                            <HardHatIcon className="w-8 h-8 mr-2 text-yellow-600"/>
                            Proyectos / Obras
                        </h2>
                        <p className="text-sm text-gray-500">Gestión de costos por proyecto</p>
                    </div>
                </div>
                {userRole === UserRole.OWNER && !isAdding && (
                    <button onClick={() => setIsAdding(true)} className="flex items-center bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg">
                        <PlusIcon className="w-5 h-5 mr-2" />
                        Nueva Obra
                    </button>
                )}
            </div>

            {isAdding && (
                <div className="mb-8 p-4 bg-gray-50 rounded-lg border border-gray-200">
                    <h3 className="font-semibold text-gray-700 mb-3 text-blue-600">Registrar Nueva Obra</h3>
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <input
                                type="text"
                                placeholder="Nombre de la Obra (Ej: Edificio Miramar)"
                                value={newProjectName}
                                onChange={e => setNewProjectName(e.target.value)}
                                className="input-style w-full p-2 border rounded"
                                required
                            />
                            <input
                                type="text"
                                placeholder="Descripción corta"
                                value={newProjectDesc}
                                onChange={e => setNewProjectDesc(e.target.value)}
                                className="input-style w-full p-2 border rounded"
                            />
                        </div>
                        <div className="flex justify-end space-x-2">
                            <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-md">Cancelar</button>
                            <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700">Crear Proyecto</button>
                        </div>
                    </form>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {projectStats.map(project => (
                    <div 
                        key={project.id} 
                        onClick={() => setSelectedProjectId(project.id)}
                        className="border border-gray-200 rounded-xl p-5 hover:border-blue-500 hover:shadow-xl transition-all cursor-pointer group bg-gray-50/30"
                    >
                        <div className="flex justify-between items-start mb-2">
                            <h3 className="font-bold text-lg text-gray-800 group-hover:text-blue-600 transition-colors uppercase">{project.name}</h3>
                            <span className="px-2 py-1 bg-green-100 text-green-800 text-[10px] font-bold uppercase rounded-full">Activo</span>
                        </div>
                        <p className="text-sm text-gray-500 mb-4 h-10 line-clamp-2">{project.description || 'Sin descripción'}</p>

                        <div className="space-y-2 border-t pt-3">
                            <div className="flex justify-between text-xs">
                                <span className="text-gray-500">Insumos retirados:</span>
                                <span className="font-medium text-gray-700">{project.totalItems}</span>
                            </div>
                            <div className="flex justify-between text-sm items-end">
                                <span className="text-gray-500 font-medium">Gasto Total:</span>
                                <span className="font-extrabold text-lg text-blue-600">${project.totalCost.toLocaleString()}</span>
                            </div>
                        </div>
                        <div className="mt-4 text-center">
                            <span className="text-xs text-blue-600 font-bold opacity-0 group-hover:opacity-100 transition-opacity">VER DETALLE DE GASTOS →</span>
                        </div>
                    </div>
                ))}
            </div>
            {projects.length === 0 && (
                <div className="text-center py-20 text-gray-400">
                    <HardHatIcon className="w-16 h-16 mx-auto mb-4 opacity-20"/>
                    <p>No hay obras registradas. Comience creando una nueva.</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { AddItemModal } from './components/AddItemModal';
import { EditItemModal } from './components/EditItemModal';
import { Dashboard } from './components/Dashboard';
import { Header } from './components/Header';
import { InventoryView } from './components/InventoryView';
import { LogMovementModal } from './components/LogMovementModal';
import { MovementsView } from './components/MovementsView';
import { AddPersonnelModal } from './components/AddPersonnelModal';
import { PersonnelView } from './components/PersonnelView';
import { AddPurchaseOrderModal } from './components/AddPurchaseOrderModal';
import { PurchaseOrdersView } from './components/PurchaseOrdersView';
import { ProjectsView } from './components/ProjectsView';
import { LoansView } from './components/LoansView';
import { ItemHistoryModal } from './components/ItemHistoryModal';
import { UserManagementModal } from './components/UserManagementModal';

import { mockItems, mockMovements, mockPersonnel, mockPurchaseOrders, mockProjects, mockUsers } from './mockData';
import { Item, Movement, MovementType, Personnel, PurchaseOrder, PurchaseOrderStatus, UserRole, InventoryType, Project, AppUser } from './types';
import { LoginView } from './components/LoginView';

// Icons for Sidebar
import { DashboardIcon } from './components/icons/DashboardIcon';
import { InventoryIcon } from './components/icons/InventoryIcon';
import { MovementsIcon } from './components/icons/MovementsIcon';
import { PersonnelIcon } from './components/icons/PersonnelIcon';
import { PurchaseOrdersIcon } from './components/icons/PurchaseOrdersIcon';
import { HandToolIcon } from './components/icons/HandToolIcon';
import { ElectricalToolIcon } from './components/icons/ElectricalToolIcon';
import { PpeIcon } from './components/icons/PpeIcon';
import { SingleUseIcon } from './components/icons/SingleUseIcon';
import { HardHatIcon } from './components/icons/HardHatIcon';
import { ClockIcon } from './components/icons/ClockIcon';

type View = 'dashboard' | 'inventory' | 'movements' | 'purchaseOrders' | 'personnel' | 'projects' | 'loans';

const App: React.FC = () => {
    // State Management
    const [isAuthenticated, setIsAuthenticated] = useState(false);

    // Users Management State
    const [users, setUsers] = useState<AppUser[]>(() => {
        try {
            const savedUsers = localStorage.getItem('inventory_users');
            return savedUsers ? JSON.parse(savedUsers) : mockUsers;
        } catch (e) {
            console.error("Failed to parse users", e);
            return mockUsers;
        }
    });

    const [items, setItems] = useState<Item[]>(() => {
        try {
            const savedItems = localStorage.getItem('inventory_items');
            return savedItems ? JSON.parse(savedItems) : mockItems;
        } catch (e) {
            console.error("Failed to parse items", e);
            return mockItems;
        }
    });

    const [movements, setMovements] = useState<Movement[]>(() => {
        try {
            const savedMovements = localStorage.getItem('inventory_movements');
            if (savedMovements) {
                return JSON.parse(savedMovements).map((m: Movement) => ({ ...m, timestamp: new Date(m.timestamp) }));
            }
            return mockMovements;
        } catch (e) {
            console.error("Failed to parse movements", e);
            return mockMovements;
        }
    });

    const [personnel, setPersonnel] = useState<Personnel[]>(() => {
        try {
            const savedPersonnel = localStorage.getItem('inventory_personnel');
            return savedPersonnel ? JSON.parse(savedPersonnel) : mockPersonnel;
        } catch (e) {
            console.error("Failed to parse personnel", e);
            return mockPersonnel;
        }
    });

    const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>(() => {
        try {
            const savedPOs = localStorage.getItem('inventory_purchase_orders');
            if (savedPOs) {
                return JSON.parse(savedPOs).map((po: PurchaseOrder) => ({
                    ...po,
                    orderDate: new Date(po.orderDate),
                    expectedDeliveryDate: po.expectedDeliveryDate ? new Date(po.expectedDeliveryDate) : undefined,
                    receivedDate: po.receivedDate ? new Date(po.receivedDate) : undefined,
                }));
            }
            return mockPurchaseOrders;
        } catch (e) {
            console.error("Failed to parse purchase orders", e);
            return mockPurchaseOrders;
        }
    });

    const [projects, setProjects] = useState<Project[]>(() => {
        try {
            const savedProjects = localStorage.getItem('inventory_projects');
            return savedProjects ? JSON.parse(savedProjects) : mockProjects;
        } catch (e) {
            console.error("Failed to parse projects", e);
            return mockProjects;
        }
    });

    const [userRole, setUserRole] = useState<UserRole>(UserRole.OWNER);

    // Persist Data Hooks
    useEffect(() => {
        localStorage.setItem('inventory_users', JSON.stringify(users));
    }, [users]);
    useEffect(() => {
        localStorage.setItem('inventory_items', JSON.stringify(items));
    }, [items]);
    useEffect(() => {
        localStorage.setItem('inventory_movements', JSON.stringify(movements));
    }, [movements]);
    useEffect(() => {
        localStorage.setItem('inventory_personnel', JSON.stringify(personnel));
    }, [personnel]);
    useEffect(() => {
        localStorage.setItem('inventory_purchase_orders', JSON.stringify(purchaseOrders));
    }, [purchaseOrders]);
    useEffect(() => {
        localStorage.setItem('inventory_projects', JSON.stringify(projects));
    }, [projects]);


    // UI State
    const [currentView, setCurrentView] = useState<View>('dashboard');
    const [selectedMovementFilter, setSelectedMovementFilter] = useState<InventoryType | null>(null);
    const [selectedSubCategory, setSelectedSubCategory] = useState<string | null>(null);
    const [selectedInventoryType, setSelectedInventoryType] = useState<InventoryType | null>(null);

    const [isSidebarOpen, setSidebarOpen] = useState(true);

    // Modal State
    const [isAddItemModalOpen, setAddItemModalOpen] = useState(false);
    const [isEditModalOpen, setEditModalOpen] = useState(false);
    const [itemToEdit, setItemToEdit] = useState<Item | null>(null);
    const [isLogMovementModalOpen, setLogMovementModalOpen] = useState(false);
    const [isAddPersonnelModalOpen, setAddPersonnelModalOpen] = useState(false);
    const [isAddPOModalOpen, setAddPOModalOpen] = useState(false);
    const [isUserManagementOpen, setUserManagementOpen] = useState(false);

    // Kardex State
    const [itemForHistory, setItemForHistory] = useState<Item | null>(null);
    const [isHistoryModalOpen, setHistoryModalOpen] = useState(false);

    const uniqueSubCategories = useMemo(() => {
        const subCategories = new Set(items.map(item => item.subCategory));
        return Array.from(subCategories).sort();
    }, [items]);

    // Handlers
    const handleLogin = (role: UserRole) => {
        setUserRole(role);
        setIsAuthenticated(true);
    }

    const handleLogout = () => {
        if (window.confirm('¿Desea cerrar sesión y volver a la pantalla de inicio?')) {
            setIsAuthenticated(false);
            setCurrentView('dashboard');
        }
    }

    const handleAddUser = (newUser: AppUser) => {
        setUsers([...users, newUser]);
    }
    const handleEditUser = (updatedUser: AppUser) => {
        setUsers(users.map(u => u.id === updatedUser.id ? updatedUser : u));
    }
    const handleDeleteUser = (id: string) => {
        setUsers(users.filter(u => u.id !== id));
    }

    const handleAddItem = (item: Omit<Item, 'id'>) => {
        const newItem: Item = { ...item, id: `item-${Date.now()}` };
        setItems(prev => [...prev, newItem]);
    };

    const handleEditItem = (updatedItem: Item) => {
        setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
        setItemToEdit(null);
    };

    const handleDeleteItem = (itemId: string) => {
        if (window.confirm('¿Está seguro de que desea eliminar este artículo?')) {
            setItems(prev => prev.filter(item => item.id !== itemId));
        }
    };

    const openEditItemModal = (item: Item) => {
        setItemToEdit(item);
        setEditModalOpen(true);
    };

    const openItemHistory = (item: Item) => {
        setItemForHistory(item);
        setHistoryModalOpen(true);
    };

    const handleLogMovement = (movement: Omit<Movement, 'id' | 'timestamp'>) => {
        const newMovement: Movement = { 
            ...movement, 
            id: `move-${Date.now()}`, 
            timestamp: new Date(),
            isReturned: false 
        };
        setMovements(prev => [newMovement, ...prev]);

        const item = items.find(i => i.id === movement.itemId);
        if (item) {
            let newQuantity = item.quantity;
            if (movement.type === MovementType.CHECK_OUT || movement.type === MovementType.WASTE) {
                newQuantity -= movement.quantity;
            } else {
                newQuantity += movement.quantity;
            }
            handleEditItem({ ...item, quantity: newQuantity });
        }
    };

    const handleReturnLoan = (movementId: string) => {
        const movement = movements.find(m => m.id === movementId);
        if (!movement || movement.isReturned) return;

        const itemName = items.find(i => i.id === movement.itemId)?.name || 'artículo';
        if (window.confirm(`¿Confirmar devolución de: ${itemName}?`)) {
            setMovements(prev => prev.map(m => m.id === movementId ? { ...m, isReturned: true } : m));
            const item = items.find(i => i.id === movement.itemId);
            if (item) {
                handleEditItem({ ...item, quantity: item.quantity + movement.quantity });
            }
        }
    };

    const handleAddPersonnel = (person: Omit<Personnel, 'id'>) => {
        const newPerson: Personnel = { ...person, id: `person-${Date.now()}` };
        setPersonnel(prev => [...prev, newPerson]);
    };

    const handleEditPersonnel = (updatedPerson: Personnel) => {
        setPersonnel(prev => prev.map(p => p.id === updatedPerson.id ? updatedPerson : p));
    };

    const handleDeletePersonnel = (id: string) => {
        if (window.confirm('¿Eliminar a esta persona del sistema?')) {
            setPersonnel(prev => prev.filter(p => p.id !== id));
        }
    };

    const handleAddProject = (project: Omit<Project, 'id'>) => {
        const newProject: Project = { ...project, id: `proj-${Date.now()}` };
        setProjects(prev => [...prev, newProject]);
    };

    const handleAddPurchaseOrder = (order: Omit<PurchaseOrder, 'id'>) => {
        const newOrder: PurchaseOrder = { ...order, id: `po-${Date.now()}` };
        setPurchaseOrders(prev => [newOrder, ...prev]);
    };

    const handleUpdatePOStatus = (orderId: string, status: PurchaseOrderStatus) => {
        setPurchaseOrders(prev => prev.map(order => {
            if (order.id === orderId) {
                const updatedOrder = { ...order, status };
                if (status === PurchaseOrderStatus.RECEIVED) {
                    updatedOrder.receivedDate = new Date();
                    updatedOrder.items.forEach(orderItem => {
                        handleLogMovement({
                            itemId: orderItem.itemId,
                            type: MovementType.PURCHASE,
                            quantity: orderItem.quantity,
                            notes: `Recibido de orden de compra #${order.id.split('-')[1]}`
                        });
                    });
                }
                return updatedOrder;
            }
            return order;
        }));
    };

    const handleExportData = () => {
        const data = { items, movements, personnel, purchaseOrders, projects, users, exportDate: new Date().toISOString() };
        const dataStr = JSON.stringify(data, null, 2);
        const blob = new Blob([dataStr], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `backup_bodega_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleImportData = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const json = e.target?.result as string;
                const data = JSON.parse(json);
                if (data.items && data.movements) {
                    if (window.confirm('¿Seguro que desea RESTAURAR los datos? Esto sobreescribirá todo lo actual.')) {
                        // Guardar todo en localStorage
                        localStorage.setItem('inventory_items', JSON.stringify(data.items));
                        localStorage.setItem('inventory_movements', JSON.stringify(data.movements));
                        if (data.personnel) localStorage.setItem('inventory_personnel', JSON.stringify(data.personnel));
                        if (data.purchaseOrders) localStorage.setItem('inventory_purchase_orders', JSON.stringify(data.purchaseOrders));
                        if (data.projects) localStorage.setItem('inventory_projects', JSON.stringify(data.projects));
                        if (data.users) localStorage.setItem('inventory_users', JSON.stringify(data.users));

                        alert('Base de datos restaurada con éxito. Reiniciando sistema...');
                        window.location.reload();
                    }
                } else {
                    alert('El archivo no es un respaldo válido de Bodega Maestra.');
                }
            } catch (error) {
                console.error("Error importing data", error);
                alert('Error crítico al procesar el archivo. Verifique que sea el archivo .json correcto.');
            }
        };
        reader.readAsText(file);
        event.target.value = '';
    };

    const handleResetData = () => {
        const password = prompt("PELIGRO: Esto borrará todo el sistema.\nIngrese la CLAVE MAESTRA para confirmar:");
        if (password === '00') {
            if (window.confirm('¿Está absolutamente seguro? Se eliminarán todos los registros.')) {
                localStorage.clear();
                alert("El sistema se ha restablecido a cero. La página se recargará.");
                window.location.reload();
            }
        } else if (password !== null) {
            alert("Contraseña incorrecta.");
        }
    };

    const filteredItems = useMemo(() => {
        let result = items;
        if (selectedInventoryType) result = result.filter(item => item.inventoryType === selectedInventoryType);
        if (selectedSubCategory) result = result.filter(item => item.subCategory === selectedSubCategory);
        return result;
    }, [items, selectedSubCategory, selectedInventoryType]);

    const selectView = (view: View) => {
        setCurrentView(view);
        setSelectedMovementFilter(null);
        setSelectedSubCategory(null);
        setSelectedInventoryType(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    const selectInventoryTypeFilter = (type: InventoryType) => {
        setCurrentView('inventory');
        setSelectedInventoryType(type);
        setSelectedSubCategory(null);
        setSelectedMovementFilter(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    const selectInventorySubCategory = (subCategory: string | null) => {
        setCurrentView('inventory');
        setSelectedSubCategory(subCategory);
        if (subCategory === null) setSelectedInventoryType(null);
        setSelectedMovementFilter(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    const renderView = () => {
        const onGoBack = () => selectView('dashboard');
        const inventoryTitle = selectedSubCategory || selectedInventoryType || 'Todos los Artículos';

        switch (currentView) {
            case 'dashboard':
                return <Dashboard items={items} movements={movements} />;
            case 'inventory':
                return <InventoryView items={filteredItems} openAddItemModal={() => setAddItemModalOpen(true)} onEditItem={openEditItemModal} onDeleteItem={handleDeleteItem} onItemHistory={openItemHistory} userRole={userRole} category={inventoryTitle} onGoBack={onGoBack} />;
            case 'movements':
                return <MovementsView movements={movements} items={items} personnel={personnel} openLogMovementModal={() => setLogMovementModalOpen(true)} onReturnLoan={handleReturnLoan} onGoBack={onGoBack} />;
            case 'purchaseOrders':
                return <PurchaseOrdersView purchaseOrders={purchaseOrders} items={items} openAddPurchaseOrderModal={() => setAddPOModalOpen(true)} onUpdateStatus={handleUpdatePOStatus} userRole={userRole} onGoBack={onGoBack} />;
            case 'personnel':
                return <PersonnelView personnel={personnel} openAddPersonnelModal={() => setAddPersonnelModalOpen(true)} onGoBack={onGoBack} onEditPersonnel={handleEditPersonnel} onDeletePersonnel={handleDeletePersonnel} userRole={userRole} />;
            case 'projects':
                return <ProjectsView projects={projects} movements={movements} items={items} personnel={personnel} onAddProject={handleAddProject} onGoBack={onGoBack} userRole={userRole} />;
            case 'loans':
                return <LoansView movements={movements} items={items} personnel={personnel} onReturnItem={handleReturnLoan} onGoBack={onGoBack} />;
            default:
                return <div>Seleccione una vista</div>;
        }
    };

    if (!isAuthenticated) return <LoginView onLoginSuccess={handleLogin} users={users} />;

    return (
        <div className="flex h-screen bg-gray-100">
            {isSidebarOpen && <div onClick={() => setSidebarOpen(false)} className="fixed inset-0 bg-black/50 z-20 md:hidden" />}
            <aside className={`bg-white border-r border-gray-200 transition-all duration-300 ease-in-out fixed md:relative inset-y-0 left-0 z-30 transform md:transform-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:${isSidebarOpen ? 'w-64' : 'w-0 overflow-hidden'} flex flex-col`}>
                <div className="h-16 flex-shrink-0 flex items-center justify-center border-b bg-blue-600 text-white"><h2 className="text-xl font-bold tracking-tighter">BODEGA MAESTRA</h2></div>
                <div className="flex-1 overflow-y-auto">
                    <nav className="p-2">
                        <NavItem icon={DashboardIcon} label="Tablero" onClick={() => selectView('dashboard')} isActive={currentView === 'dashboard'} />
                        <NavHeader label="Operación" />
                        <NavItem icon={HardHatIcon} label="Proyectos / Obras" onClick={() => selectView('projects')} isActive={currentView === 'projects'} />
                        <NavItem icon={ClockIcon} label="Préstamos / Devol." onClick={() => selectView('loans')} isActive={currentView === 'loans'} />
                        <NavItem icon={MovementsIcon} label="Movimientos" onClick={() => selectView('movements')} isActive={currentView === 'movements'} />
                        <NavHeader label="Categorías" />
                        <NavItem icon={HandToolIcon} label="Herramienta Manual" onClick={() => selectInventoryTypeFilter(InventoryType.HAND_TOOL)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.HAND_TOOL} />
                        <NavItem icon={ElectricalToolIcon} label="Herramienta Eléctrica" onClick={() => selectInventoryTypeFilter(InventoryType.ELECTRICAL_TOOL)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.ELECTRICAL_TOOL} />
                        <NavItem icon={PpeIcon} label="Indumentaria (EPP)" onClick={() => selectInventoryTypeFilter(InventoryType.PPE)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.PPE} />
                        <NavItem icon={SingleUseIcon} label="Material de Consumo" onClick={() => selectInventoryTypeFilter(InventoryType.SINGLE_USE)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.SINGLE_USE} />
                        <NavHeader label="Administración" />
                        <NavItem icon={PurchaseOrdersIcon} label="Órdenes de Compra" onClick={() => selectView('purchaseOrders')} isActive={currentView === 'purchaseOrders'}/>
                        <NavItem icon={PersonnelIcon} label="Personal" onClick={() => selectView('personnel')} isActive={currentView === 'personnel'} />
                    </nav>
                </div>
                <div className="p-4 border-t bg-gray-50">
                    <button onClick={handleLogout} className="w-full flex items-center justify-center px-4 py-2 bg-red-500 hover:bg-red-600 text-white rounded-lg font-bold text-xs transition-colors">
                        SALIR / CAMBIAR USUARIO
                    </button>
                </div>
            </aside>
            <div className="flex-1 flex flex-col">
                <Header toggleSidebar={() => setSidebarOpen(!isSidebarOpen)} userRole={userRole} setUserRole={setUserRole} onExportData={handleExportData} onImportData={handleImportData} onResetData={handleResetData} onOpenUserManagement={() => setUserManagementOpen(true)} onLogout={handleLogout} />
                <main className="flex-1 p-4 md:p-6 overflow-y-auto">{renderView()}</main>
            </div>
            <AddItemModal isOpen={isAddItemModalOpen} onClose={() => setAddItemModalOpen(false)} onAddItem={handleAddItem} userRole={userRole} />
            <EditItemModal isOpen={isEditModalOpen} onClose={() => setEditModalOpen(false)} onEditItem={handleEditItem} itemToEdit={itemToEdit} />
            <LogMovementModal isOpen={isLogMovementModalOpen} onClose={() => setLogMovementModalOpen(false)} onLogMovement={handleLogMovement} items={items} personnel={personnel} projects={projects} userRole={userRole} filterInventoryType={selectedInventoryType || undefined} />
            <AddPersonnelModal isOpen={isAddPersonnelModalOpen} onClose={() => setAddPersonnelModalOpen(false)} onAddPersonnel={handleAddPersonnel} />
            <AddPurchaseOrderModal isOpen={isAddPOModalOpen} onClose={() => setAddPOModalOpen(false)} onAddPurchaseOrder={handleAddPurchaseOrder} items={items} />
            <ItemHistoryModal isOpen={isHistoryModalOpen} onClose={() => setHistoryModalOpen(false)} item={itemForHistory} movements={movements} personnel={personnel} />
            <UserManagementModal isOpen={isUserManagementOpen} onClose={() => setUserManagementOpen(false)} users={users} onAddUser={handleAddUser} onDeleteUser={handleDeleteUser} onEditUser={handleEditUser} />
        </div>
    );
};

const NavItem: React.FC<{ icon: React.ElementType, label: string, onClick: () => void, isActive: boolean, isSubItem?: boolean }> = ({ icon: Icon, label, onClick, isActive, isSubItem = false }) => (
    <button onClick={onClick} className={`w-full flex items-center text-left px-4 py-2.5 text-sm font-medium rounded-lg transition-colors duration-200 ${isSubItem ? 'pl-8' : ''} ${isActive ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-600 hover:bg-gray-100'}`}>
        <Icon className="w-5 h-5 mr-3" />
        {label}
    </button>
);

const NavHeader: React.FC<{label: string}> = ({label}) => <h3 className="px-4 pt-4 pb-2 text-xs font-semibold text-gray-500 uppercase tracking-wider">{label}</h3>;

export default App;

import React, { useState, useMemo } from 'react';
import { Project, Movement, Item, UserRole, MovementType, Personnel } from '../types';
import { PlusIcon } from './icons/PlusIcon';
import { ArrowLeftIcon } from './icons/ArrowLeftIcon';
import { HardHatIcon } from './icons/HardHatIcon';

interface ProjectsViewProps {
    projects: Project[];
    movements: Movement[];
    items: Item[];
    personnel: Personnel[];
    onAddProject: (project: Omit<Project, 'id'>) => void;
    onGoBack: () => void;
    userRole: UserRole;
}

export const ProjectsView: React.FC<ProjectsViewProps> = ({ projects, movements, items, personnel, onAddProject, onGoBack, userRole }) => {
    const [isAdding, setIsAdding] = useState(false);
    const [newProjectName, setNewProjectName] = useState('');
    const [newProjectDesc, setNewProjectDesc] = useState('');
    const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

    const projectStats = useMemo(() => {
        return projects.map(project => {
            const projectMovements = movements.filter(m => m.projectId === project.id && (m.type === MovementType.CHECK_OUT || m.type === MovementType.WASTE));
            const totalItems = projectMovements.reduce((acc, m) => acc + m.quantity, 0);
            const totalCost = projectMovements.reduce((acc, m) => {
                const item = items.find(i => i.id === m.itemId);
                return acc + (item ? item.price * m.quantity : 0);
            }, 0);
            return { ...project, totalItems, totalCost };
        });
    }, [projects, movements, items]);

    const selectedProject = useMemo(() => 
        projectStats.find(p => p.id === selectedProjectId), 
    [projectStats, selectedProjectId]);

    const detailedMovements = useMemo(() => {
        if (!selectedProjectId) return [];
        return movements
            .filter(m => m.projectId === selectedProjectId && (m.type === MovementType.CHECK_OUT || m.type === MovementType.WASTE))
            .map(m => {
                const item = items.find(i => i.id === m.itemId);
                const person = personnel.find(p => p.id === m.personnelId);
                return {
                    ...m,
                    itemName: item?.name || 'Desconocido',
                    personName: person?.name || 'Sin asignar',
                    price: item?.price || 0,
                    subtotal: (item?.price || 0) * m.quantity
                };
            })
            .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [movements, items, personnel, selectedProjectId]);

    // Resumen acumulado por material
    const materialSummary = useMemo(() => {
        const summary: { [key: string]: { name: string, quantity: number, cost: number } } = {};
        detailedMovements.forEach(m => {
            if (!summary[m.itemId]) {
                summary[m.itemId] = { name: m.itemName, quantity: 0, cost: 0 };
            }
            summary[m.itemId].quantity += m.quantity;
            summary[m.itemId].cost += m.subtotal;
        });
        return Object.values(summary).sort((a, b) => b.cost - a.cost);
    }, [detailedMovements]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newProjectName.trim()) return;
        onAddProject({ name: newProjectName, description: newProjectDesc, status: 'active' });
        setIsAdding(false);
        setNewProjectName('');
        setNewProjectDesc('');
    };

    if (selectedProject) {
        return (
            <div className="space-y-6 animate-in fade-in duration-300">
                <div className="bg-white p-6 rounded-xl shadow-lg border-t-4 border-blue-600">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div className="flex items-center">
                            <button onClick={() => setSelectedProjectId(null)} className="mr-4 p-2 rounded-full bg-gray-100 hover:bg-gray-200 transition-colors">
                                <ArrowLeftIcon className="w-6 h-6 text-gray-700" />
                            </button>
                            <div>
                                <h2 className="text-3xl font-extrabold text-gray-900 uppercase tracking-tight">{selectedProject.name}</h2>
                                <p className="text-gray-500 font-medium">Historial completo de gastos y materiales</p>
                            </div>
                        </div>
                        <div className="bg-blue-50 px-6 py-4 rounded-xl border border-blue-100 flex flex-col items-center justify-center">
                            <span className="text-[10px] text-blue-600 font-black uppercase tracking-widest">Inversión Total en Obra</span>
                            <span className="text-4xl font-black text-blue-700">${selectedProject.totalCost.toLocaleString()}</span>
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Tabla de Desglose Paso a Paso */}
                    <div className="lg:col-span-2 bg-white rounded-xl shadow-md overflow-hidden">
                        <div className="p-4 bg-gray-50 border-b flex justify-between items-center">
                            <h3 className="font-bold text-gray-700 flex items-center">
                                <ClockIcon className="w-5 h-5 mr-2 text-blue-500" />
                                Bitácora de Salidas
                            </h3>
                            <span className="text-xs font-bold text-gray-400">{detailedMovements.length} movimientos</span>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="min-w-full divide-y divide-gray-200">
                                <thead className="bg-gray-50/50">
                                    <tr>
                                        <th className="px-4 py-3 text-left text-[10px] font-black text-gray-400 uppercase">Fecha / Personal</th>
                                        <th className="px-4 py-3 text-left text-[10px] font-black text-gray-400 uppercase">Material</th>
                                        <th className="px-4 py-3 text-center text-[10px] font-black text-gray-400 uppercase">Cant.</th>
                                        <th className="px-4 py-3 text-right text-[10px] font-black text-gray-400 uppercase">Gasto</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {detailedMovements.map(m => (
                                        <tr key={m.id} className="hover:bg-blue-50/30 transition-colors">
                                            <td className="px-4 py-3">
                                                <div className="text-[11px] font-bold text-gray-800">{new Date(m.timestamp).toLocaleDateString()}</div>
                                                <div className="text-[10px] text-gray-500 truncate w-32">{m.personName}</div>
                                            </td>
                                            <td className="px-4 py-3">
                                                <div className="text-sm font-bold text-gray-900">{m.itemName}</div>
                                                {m.isLoan && <span className="text-[9px] bg-orange-100 text-orange-700 px-1 rounded font-bold">PRÉSTAMO</span>}
                                            </td>
                                            <td className="px-4 py-3 text-center font-black text-gray-700">{m.quantity}</td>
                                            <td className="px-4 py-3 text-right">
                                                <div className="text-sm font-black text-blue-600">${m.subtotal.toLocaleString()}</div>
                                                <div className="text-[9px] text-gray-400">${m.price.toFixed(2)} c/u</div>
                                            </td>
                                        </tr>
                                    ))}
                                    {detailedMovements.length === 0 && (
                                        <tr>
                                            <td colSpan={4} className="py-20 text-center text-gray-400 italic">No se han registrado retiros para esta obra.</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>

                    {/* Resumen Acumulado por Insumo */}
                    <div className="bg-white rounded-xl shadow-md overflow-hidden">
                        <div className="p-4 bg-gray-50 border-b">
                            <h3 className="font-bold text-gray-700">Resumen por Material</h3>
                        </div>
                        <div className="p-4 space-y-4">
                            {materialSummary.map(mat => (
                                <div key={mat.name} className="flex flex-col border-b border-gray-100 pb-2">
                                    <div className="flex justify-between items-start">
                                        <span className="text-sm font-bold text-gray-800 truncate w-48">{mat.name}</span>
                                        <span className="text-sm font-black text-blue-600">${mat.cost.toLocaleString()}</span>
                                    </div>
                                    <div className="flex justify-between text-[10px] text-gray-500 mt-1">
                                        <span>Total consumido:</span>
                                        <span className="font-bold">{mat.quantity} unidades</span>
                                    </div>
                                    <div className="mt-2 w-full bg-gray-100 h-1.5 rounded-full overflow-hidden">
                                        <div 
                                            className="bg-blue-500 h-full rounded-full" 
                                            style={{ width: `${Math.min((mat.cost / (selectedProject.totalCost || 1)) * 100, 100)}%` }}
                                        ></div>
                                    </div>
                                </div>
                            ))}
                            {materialSummary.length === 0 && (
                                <p className="text-center py-10 text-gray-400 text-sm">Sin datos acumulados.</p>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-md flex flex-col md:flex-row justify-between items-start md:items-center">
                 <div className="flex items-center mb-4 md:mb-0">
                    <button onClick={onGoBack} className="mr-4 p-2 rounded-full hover:bg-gray-100">
                        <ArrowLeftIcon className="w-6 h-6 text-gray-600" />
                    </button>
                    <div>
                        <h2 className="text-2xl font-black text-gray-800 flex items-center">
                            <HardHatIcon className="w-8 h-8 mr-2 text-yellow-600"/>
                            PROYECTOS Y OBRAS
                        </h2>
                        <p className="text-sm text-gray-500 font-medium uppercase tracking-wider">Control de costos y materiales por proyecto</p>
                    </div>
                </div>
                {userRole === UserRole.OWNER && !isAdding && (
                    <button onClick={() => setIsAdding(true)} className="flex items-center bg-blue-600 hover:bg-blue-700 text-white font-black py-3 px-6 rounded-xl shadow-lg transition-all transform hover:scale-105">
                        <PlusIcon className="w-5 h-5 mr-2" />
                        CREAR NUEVA OBRA
                    </button>
                )}
            </div>

            {isAdding && (
                <div className="p-6 bg-white rounded-xl shadow-xl border-2 border-blue-500 animate-in slide-in-from-top duration-300">
                    <h3 className="font-black text-gray-800 mb-6 text-xl uppercase">Registrar Nueva Obra en el Sistema</h3>
                    <form onSubmit={handleSubmit} className="space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase mb-2">Nombre de la Obra</label>
                                <input
                                    type="text"
                                    placeholder="Ej: Edificio Miramar Piso 5"
                                    value={newProjectName}
                                    onChange={e => setNewProjectName(e.target.value)}
                                    className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold text-gray-700 transition-colors"
                                    required
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-black text-gray-400 uppercase mb-2">Descripción General / Ubicación</label>
                                <input
                                    type="text"
                                    placeholder="Opcional"
                                    value={newProjectDesc}
                                    onChange={e => setNewProjectDesc(e.target.value)}
                                    className="w-full p-4 border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold text-gray-700 transition-colors"
                                />
                            </div>
                        </div>
                        <div className="flex justify-end space-x-4">
                            <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-3 text-gray-500 font-bold hover:bg-gray-100 rounded-xl transition-colors">DESCARTAR</button>
                            <button type="submit" className="px-8 py-3 bg-blue-600 text-white font-black rounded-xl hover:bg-blue-700 shadow-md">CONFIRMAR Y CREAR</button>
                        </div>
                    </form>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {projectStats.map(project => (
                    <div 
                        key={project.id} 
                        onClick={() => setSelectedProjectId(project.id)}
                        className="group bg-white border border-gray-200 rounded-2xl p-6 hover:border-blue-500 hover:shadow-2xl transition-all cursor-pointer relative overflow-hidden"
                    >
                        <div className="absolute top-0 right-0 p-4">
                            <span className="bg-green-100 text-green-700 text-[9px] font-black px-3 py-1 rounded-full uppercase">En Obra</span>
                        </div>
                        <h3 className="font-black text-xl text-gray-800 group-hover:text-blue-600 transition-colors uppercase leading-tight mb-2 pr-16">{project.name}</h3>
                        <p className="text-xs text-gray-500 font-medium mb-8 h-8 line-clamp-2 uppercase tracking-wide">{project.description || 'SIN DESCRIPCIÓN REGISTRADA'}</p>

                        <div className="grid grid-cols-2 gap-4 border-t pt-4">
                            <div>
                                <span className="text-[9px] text-gray-400 font-black uppercase block mb-1">Insumos Salidos</span>
                                <span className="text-lg font-black text-gray-700">{project.totalItems}</span>
                            </div>
                            <div className="text-right">
                                <span className="text-[9px] text-gray-400 font-black uppercase block mb-1">Gasto Total</span>
                                <span className="text-lg font-black text-blue-600">${project.totalCost.toLocaleString()}</span>
                            </div>
                        </div>
                        <div className="mt-6 w-full py-3 bg-gray-50 group-hover:bg-blue-600 text-blue-600 group-hover:text-white rounded-xl text-center text-xs font-black transition-all uppercase tracking-widest">
                            VER DETALLES DE GASTOS
                        </div>
                    </div>
                ))}
            </div>
            {projects.length === 0 && (
                <div className="text-center py-32 bg-white rounded-3xl border-2 border-dashed border-gray-200">
                    <HardHatIcon className="w-20 h-20 mx-auto mb-6 opacity-10 text-gray-800"/>
                    <p className="text-xl font-bold text-gray-400 uppercase tracking-tighter">No hay obras registradas. Comience creando una nueva arriba.</p>
                </div>
            )}
        </div>
    );
};

const ClockIcon = ({ className }: { className?: string }) => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className={className}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
);

import React, { useState } from 'react';
import { AppUser, UserRole } from '../types';
import { XIcon } from './icons/XIcon';
import { TrashIcon } from './icons/TrashIcon';
import { EditIcon } from './icons/EditIcon';

interface UserManagementModalProps {
    isOpen: boolean;
    onClose: () => void;
    users: AppUser[];
    onAddUser: (user: AppUser) => void;
    onDeleteUser: (id: string) => void;
    onEditUser: (user: AppUser) => void;
}

export const UserManagementModal: React.FC<UserManagementModalProps> = ({ isOpen, onClose, users, onAddUser, onDeleteUser, onEditUser }) => {
    const [newUsername, setNewUsername] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [newName, setNewName] = useState('');
    const [newRole, setNewRole] = useState<UserRole>(UserRole.EMPLOYEE);
    const [editingUserId, setEditingUserId] = useState<string | null>(null);

    if (!isOpen) return null;

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!newUsername.trim() || !newPassword.trim() || !newName.trim()) {
            alert("Todos los campos son obligatorios");
            return;
        }

        if (!editingUserId && users.some(u => u.username === newUsername)) {
            alert("El nombre de usuario ya existe.");
            return;
        }

        if (editingUserId) {
            const updatedUser: AppUser = {
                id: editingUserId,
                username: newUsername,
                password: newPassword,
                name: newName,
                role: newRole
            };
            onEditUser(updatedUser);
            setEditingUserId(null);
        } else {
            const newUser: AppUser = {
                id: `user-${Date.now()}`,
                username: newUsername,
                password: newPassword,
                name: newName,
                role: newRole
            };
            onAddUser(newUser);
        }

        setNewUsername('');
        setNewPassword('');
        setNewName('');
        setNewRole(UserRole.EMPLOYEE);
    };

    const handleEditClick = (user: AppUser) => {
        setEditingUserId(user.id);
        setNewUsername(user.username);
        setNewPassword(user.password);
        setNewName(user.name);
        setNewRole(user.role);
    };

    const handleCancelEdit = () => {
        setEditingUserId(null);
        setNewUsername('');
        setNewPassword('');
        setNewName('');
        setNewRole(UserRole.EMPLOYEE);
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50">
            <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-2xl m-4 max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-2xl font-bold text-gray-800">Seguridad y Usuarios</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><XIcon className="w-6 h-6" /></button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="bg-gray-50 p-6 rounded-2xl h-fit border border-gray-100">
                        <h3 className="font-black text-sm mb-4 text-blue-700 uppercase tracking-widest">
                            {editingUserId ? 'Editar Acceso' : 'Nuevo Usuario'}
                        </h3>
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase">Nombre Completo</label>
                                <input
                                    type="text"
                                    value={newName}
                                    onChange={e => setNewName(e.target.value)}
                                    className="w-full p-3 border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase">Usuario para Login</label>
                                <input
                                    type="text"
                                    value={newUsername}
                                    onChange={e => setNewUsername(e.target.value)}
                                    className="w-full p-3 border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase">Contraseña</label>
                                <input
                                    type="password"
                                    placeholder="••••••••"
                                    value={newPassword}
                                    onChange={e => setNewPassword(e.target.value)}
                                    className="w-full p-3 border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase">Nivel de Permisos</label>
                                <select 
                                    value={newRole}
                                    onChange={e => setNewRole(e.target.value as UserRole)}
                                    className="w-full p-3 border-2 border-gray-100 rounded-xl outline-none font-bold"
                                >
                                    <option value={UserRole.EMPLOYEE}>Bodeguero / Empleado</option>
                                    <option value={UserRole.OWNER}>Administrador Supremo</option>
                                </select>
                            </div>

                            <div className="flex space-x-2 pt-2">
                                {editingUserId && (
                                    <button type="button" onClick={handleCancelEdit} className="flex-1 bg-gray-200 text-gray-600 py-3 rounded-xl hover:bg-gray-300 font-bold uppercase text-xs transition-colors">
                                        Cancelar
                                    </button>
                                )}
                                <button type="submit" className="flex-1 bg-blue-600 text-white py-3 rounded-xl hover:bg-blue-700 font-bold uppercase text-xs shadow-md">
                                    {editingUserId ? 'Actualizar' : 'Guardar Acceso'}
                                </button>
                            </div>
                        </form>
                    </div>

                    <div>
                        <h3 className="font-black text-sm mb-4 text-gray-400 uppercase tracking-widest">Personal con Acceso</h3>
                        <div className="space-y-3">
                            {users.map(user => (
                                <div key={user.id} className={`flex justify-between items-center border-2 p-4 rounded-2xl transition-all ${editingUserId === user.id ? 'bg-blue-50 border-blue-400' : 'bg-white border-gray-50'}`}>
                                    <div>
                                        <p className="font-black text-gray-800 uppercase text-xs">{user.username}</p>
                                        <p className="text-[10px] text-gray-400 font-bold">{user.name}</p>
                                        <span className={`text-[9px] font-black px-2 py-0.5 rounded-full uppercase ${user.role === UserRole.OWNER ? 'bg-indigo-100 text-indigo-700' : 'bg-gray-100 text-gray-600'}`}>
                                            {user.role === UserRole.OWNER ? 'Admin Supremo' : 'Bodeguero'}
                                        </span>
                                    </div>
                                    <div className="flex space-x-1">
                                        <button 
                                            onClick={() => handleEditClick(user)}
                                            className="p-2 text-blue-500 hover:bg-blue-100 rounded-full transition-colors"
                                            title="Editar"
                                        >
                                            <EditIcon className="w-5 h-5"/>
                                        </button>
                                        {user.username !== 'juli' && (
                                            <button 
                                                onClick={() => {
                                                    if(window.confirm(`¿Seguro que desea eliminar el acceso de ${user.username}?`)) onDeleteUser(user.id);
                                                }}
                                                className="p-2 text-red-500 hover:bg-red-100 rounded-full transition-colors"
                                                title="Eliminar"
                                            >
                                                <TrashIcon className="w-5 h-5"/>
                                            </button>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { AddItemModal } from './components/AddItemModal';
import { EditItemModal } from './components/EditItemModal';
import { Dashboard } from './components/Dashboard';
import { Header } from './components/Header';
import { InventoryView } from './components/InventoryView';
import { LogMovementModal } from './components/LogMovementModal';
import { MovementsView } from './components/MovementsView';
import { AddPersonnelModal } from './components/AddPersonnelModal';
import { PersonnelView } from './components/PersonnelView';
import { AddPurchaseOrderModal } from './components/AddPurchaseOrderModal';
import { PurchaseOrdersView } from './components/PurchaseOrdersView';
import { ProjectsView } from './components/ProjectsView';
import { LoansView } from './components/LoansView';
import { ItemHistoryModal } from './components/ItemHistoryModal';
import { UserManagementModal } from './components/UserManagementModal';

import { mockItems, mockMovements, mockPersonnel, mockPurchaseOrders, mockProjects, mockUsers } from './mockData';
import { Item, Movement, MovementType, Personnel, PurchaseOrder, PurchaseOrderStatus, UserRole, InventoryType, Project, AppUser } from './types';
import { LoginView } from './components/LoginView';

// Icons for Sidebar
import { DashboardIcon } from './components/icons/DashboardIcon';
import { InventoryIcon } from './components/icons/InventoryIcon';
import { MovementsIcon } from './components/icons/MovementsIcon';
import { PersonnelIcon } from './components/icons/PersonnelIcon';
import { PurchaseOrdersIcon } from './components/icons/PurchaseOrdersIcon';
import { HandToolIcon } from './components/icons/HandToolIcon';
import { ElectricalToolIcon } from './components/icons/ElectricalToolIcon';
import { PpeIcon } from './components/icons/PpeIcon';
import { SingleUseIcon } from './components/icons/SingleUseIcon';
import { HardHatIcon } from './components/icons/HardHatIcon';
import { ClockIcon } from './components/icons/ClockIcon';
import { LogOutIcon } from './components/icons/LogOutIcon';

type View = 'dashboard' | 'inventory' | 'movements' | 'purchaseOrders' | 'personnel' | 'projects' | 'loans';

const App: React.FC = () => {
    // State Management
    const [isAuthenticated, setIsAuthenticated] = useState(false);

    // Users Management State
    const [users, setUsers] = useState<AppUser[]>(() => {
        try {
            const savedUsers = localStorage.getItem('inventory_users');
            return savedUsers ? JSON.parse(savedUsers) : mockUsers;
        } catch (e) {
            console.error("Failed to parse users", e);
            return mockUsers;
        }
    });

    const [items, setItems] = useState<Item[]>(() => {
        try {
            const savedItems = localStorage.getItem('inventory_items');
            return savedItems ? JSON.parse(savedItems) : mockItems;
        } catch (e) {
            console.error("Failed to parse items", e);
            return mockItems;
        }
    });

    const [movements, setMovements] = useState<Movement[]>(() => {
        try {
            const savedMovements = localStorage.getItem('inventory_movements');
            if (savedMovements) {
                return JSON.parse(savedMovements).map((m: Movement) => ({ ...m, timestamp: new Date(m.timestamp) }));
            }
            return mockMovements;
        } catch (e) {
            console.error("Failed to parse movements", e);
            return mockMovements;
        }
    });

    const [personnel, setPersonnel] = useState<Personnel[]>(() => {
        try {
            const savedPersonnel = localStorage.getItem('inventory_personnel');
            return savedPersonnel ? JSON.parse(savedPersonnel) : mockPersonnel;
        } catch (e) {
            console.error("Failed to parse personnel", e);
            return mockPersonnel;
        }
    });

    const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>(() => {
        try {
            const savedPOs = localStorage.getItem('inventory_purchase_orders');
            if (savedPOs) {
                return JSON.parse(savedPOs).map((po: PurchaseOrder) => ({
                    ...po,
                    orderDate: new Date(po.orderDate),
                    expectedDeliveryDate: po.expectedDeliveryDate ? new Date(po.expectedDeliveryDate) : undefined,
                    receivedDate: po.receivedDate ? new Date(po.receivedDate) : undefined,
                }));
            }
            return mockPurchaseOrders;
        } catch (e) {
            console.error("Failed to parse purchase orders", e);
            return mockPurchaseOrders;
        }
    });

    const [projects, setProjects] = useState<Project[]>(() => {
        try {
            const savedProjects = localStorage.getItem('inventory_projects');
            return savedProjects ? JSON.parse(savedProjects) : mockProjects;
        } catch (e) {
            console.error("Failed to parse projects", e);
            return mockProjects;
        }
    });

    const [userRole, setUserRole] = useState<UserRole>(UserRole.OWNER);

    // Persist Data Hooks
    useEffect(() => {
        localStorage.setItem('inventory_users', JSON.stringify(users));
    }, [users]);
    useEffect(() => {
        localStorage.setItem('inventory_items', JSON.stringify(items));
    }, [items]);
    useEffect(() => {
        localStorage.setItem('inventory_movements', JSON.stringify(movements));
    }, [movements]);
    useEffect(() => {
        localStorage.setItem('inventory_personnel', JSON.stringify(personnel));
    }, [personnel]);
    useEffect(() => {
        localStorage.setItem('inventory_purchase_orders', JSON.stringify(purchaseOrders));
    }, [purchaseOrders]);
    useEffect(() => {
        localStorage.setItem('inventory_projects', JSON.stringify(projects));
    }, [projects]);


    // UI State
    const [currentView, setCurrentView] = useState<View>('dashboard');
    const [selectedSubCategory, setSelectedSubCategory] = useState<string | null>(null);
    const [selectedInventoryType, setSelectedInventoryType] = useState<InventoryType | null>(null);
    const [isSidebarOpen, setSidebarOpen] = useState(true);

    // Modal State
    const [isAddItemModalOpen, setAddItemModalOpen] = useState(false);
    const [isEditModalOpen, setEditModalOpen] = useState(false);
    const [itemToEdit, setItemToEdit] = useState<Item | null>(null);
    const [isLogMovementModalOpen, setLogMovementModalOpen] = useState(false);
    const [isAddPersonnelModalOpen, setAddPersonnelModalOpen] = useState(false);
    const [isAddPOModalOpen, setAddPOModalOpen] = useState(false);
    const [isUserManagementOpen, setUserManagementOpen] = useState(false);

    // Kardex State
    const [itemForHistory, setItemForHistory] = useState<Item | null>(null);
    const [isHistoryModalOpen, setHistoryModalOpen] = useState(false);

    const uniqueSubCategories = useMemo(() => {
        const subCategories = new Set(items.map(item => item.subCategory));
        return Array.from(subCategories).sort();
    }, [items]);

    // Handlers
    const handleLogin = (role: UserRole) => {
        setUserRole(role);
        setIsAuthenticated(true);
    }

    const handleLogout = () => {
        if (window.confirm('¿Está seguro de que desea cerrar sesión para cambiar de usuario?')) {
            setIsAuthenticated(false);
            setCurrentView('dashboard');
        }
    }

    const handleAddUser = (newUser: AppUser) => {
        setUsers([...users, newUser]);
    }
    const handleEditUser = (updatedUser: AppUser) => {
        setUsers(users.map(u => u.id === updatedUser.id ? updatedUser : u));
    }
    const handleDeleteUser = (id: string) => {
        setUsers(users.filter(u => u.id !== id));
    }

    const handleAddItem = (item: Omit<Item, 'id'>) => {
        const newItem: Item = { ...item, id: `item-${Date.now()}` };
        setItems(prev => [...prev, newItem]);
    };

    const handleEditItem = (updatedItem: Item) => {
        setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
        setItemToEdit(null);
    };

    const handleDeleteItem = (itemId: string) => {
        if (window.confirm('¿Está seguro de que desea eliminar este artículo?')) {
            setItems(prev => prev.filter(item => item.id !== itemId));
        }
    };

    const openEditItemModal = (item: Item) => {
        setItemToEdit(item);
        setEditModalOpen(true);
    };

    const openItemHistory = (item: Item) => {
        setItemForHistory(item);
        setHistoryModalOpen(true);
    };

    const handleLogMovement = (movement: Omit<Movement, 'id' | 'timestamp'>) => {
        const newMovement: Movement = { 
            ...movement, 
            id: `move-${Date.now()}`, 
            timestamp: new Date(),
            isReturned: false 
        };
        setMovements(prev => [newMovement, ...prev]);

        const item = items.find(i => i.id === movement.itemId);
        if (item) {
            let newQuantity = item.quantity;
            if (movement.type === MovementType.CHECK_OUT || movement.type === MovementType.WASTE) {
                newQuantity -= movement.quantity;
            } else {
                newQuantity += movement.quantity;
            }
            handleEditItem({ ...item, quantity: newQuantity });
        }
    };

    const handleReturnLoan = (movementId: string) => {
        const movement = movements.find(m => m.id === movementId);
        if (!movement || movement.isReturned) return;

        const itemName = items.find(i => i.id === movement.itemId)?.name || 'artículo';
        if (window.confirm(`¿Confirmar devolución de: ${itemName}?`)) {
            setMovements(prev => prev.map(m => m.id === movementId ? { ...m, isReturned: true } : m));
            const item = items.find(i => i.id === movement.itemId);
            if (item) {
                handleEditItem({ ...item, quantity: item.quantity + movement.quantity });
            }
        }
    };

    const handleAddPersonnel = (person: Omit<Personnel, 'id'>) => {
        const newPerson: Personnel = { ...person, id: `person-${Date.now()}` };
        setPersonnel(prev => [...prev, newPerson]);
    };

    const handleEditPersonnel = (updatedPerson: Personnel) => {
        setPersonnel(prev => prev.map(p => p.id === updatedPerson.id ? updatedPerson : p));
    };

    const handleDeletePersonnel = (id: string) => {
        if (window.confirm('¿Eliminar a esta persona del sistema?')) {
            setPersonnel(prev => prev.filter(p => p.id !== id));
        }
    };

    const handleAddProject = (project: Omit<Project, 'id'>) => {
        const newProject: Project = { ...project, id: `proj-${Date.now()}` };
        setProjects(prev => [...prev, newProject]);
    };

    const handleAddPurchaseOrder = (order: Omit<PurchaseOrder, 'id'>) => {
        const newOrder: PurchaseOrder = { ...order, id: `po-${Date.now()}` };
        setPurchaseOrders(prev => [newOrder, ...prev]);
    };

    const handleUpdatePOStatus = (orderId: string, status: PurchaseOrderStatus) => {
        setPurchaseOrders(prev => prev.map(order => {
            if (order.id === orderId) {
                const updatedOrder = { ...order, status };
                if (status === PurchaseOrderStatus.RECEIVED) {
                    updatedOrder.receivedDate = new Date();
                    updatedOrder.items.forEach(orderItem => {
                        handleLogMovement({
                            itemId: orderItem.itemId,
                            type: MovementType.PURCHASE,
                            quantity: orderItem.quantity,
                            notes: `Recibido de orden de compra #${order.id.split('-')[1]}`
                        });
                    });
                }
                return updatedOrder;
            }
            return order;
        }));
    };

    const handleExportData = () => {
        const data = { 
            items, 
            movements, 
            personnel, 
            purchaseOrders, 
            projects, 
            users, 
            exportDate: new Date().toISOString() 
        };
        const dataStr = JSON.stringify(data, null, 2);
        const blob = new Blob([dataStr], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `respaldo_bodega_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleImportData = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const json = e.target?.result as string;
                const data = JSON.parse(json);
                // Validación básica de estructura
                if (data.items && Array.isArray(data.items) && data.movements && Array.isArray(data.movements)) {
                    if (window.confirm('¡AVISO! Esta acción SOBREESCRIBIRÁ todos los datos actuales por los del respaldo. ¿Desea continuar?')) {
                        // Guardar en LocalStorage para que persista tras el reload
                        localStorage.setItem('inventory_items', JSON.stringify(data.items));
                        localStorage.setItem('inventory_movements', JSON.stringify(data.movements));
                        if (data.personnel) localStorage.setItem('inventory_personnel', JSON.stringify(data.personnel));
                        if (data.purchaseOrders) localStorage.setItem('inventory_purchase_orders', JSON.stringify(data.purchaseOrders));
                        if (data.projects) localStorage.setItem('inventory_projects', JSON.stringify(data.projects));
                        if (data.users) localStorage.setItem('inventory_users', JSON.stringify(data.users));

                        alert('Respaldo restaurado con éxito. El sistema se reiniciará para cargar los nuevos datos.');
                        window.location.reload();
                    }
                } else {
                    alert('Error: El formato del archivo de respaldo no es válido o está incompleto.');
                }
            } catch (error) {
                console.error("Error importing data", error);
                alert('Error crítico al procesar el archivo. Asegúrese de que sea un archivo JSON válido exportado por esta aplicación.');
            }
        };
        reader.readAsText(file);
        event.target.value = ''; // Limpiar input para permitir subir el mismo archivo después si es necesario
    };

    const handleResetData = () => {
        const password = prompt("ADVERTENCIA DE SEGURIDAD: Esto borrará permanentemente toda la base de datos.\nIngrese la CLAVE MAESTRA para confirmar:");
        if (password === '00') {
            if (window.confirm('¿Está ABSOLUTAMENTE SEGURO? No podrá recuperar los datos a menos que tenga un respaldo.')) {
                localStorage.clear();
                alert("Base de datos purgada. Reiniciando sistema...");
                window.location.reload();
            }
        } else if (password !== null) {
            alert("Clave maestra incorrecta.");
        }
    };

    const filteredItems = useMemo(() => {
        let result = items;
        if (selectedInventoryType) result = result.filter(item => item.inventoryType === selectedInventoryType);
        if (selectedSubCategory) result = result.filter(item => item.subCategory === selectedSubCategory);
        return result;
    }, [items, selectedSubCategory, selectedInventoryType]);

    const selectView = (view: View) => {
        setCurrentView(view);
        setSelectedSubCategory(null);
        setSelectedInventoryType(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    const selectInventoryTypeFilter = (type: InventoryType) => {
        setCurrentView('inventory');
        setSelectedInventoryType(type);
        setSelectedSubCategory(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    const selectInventorySubCategory = (subCategory: string | null) => {
        setCurrentView('inventory');
        setSelectedSubCategory(subCategory);
        if (subCategory === null) setSelectedInventoryType(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    const renderView = () => {
        const onGoBack = () => selectView('dashboard');
        const inventoryTitle = selectedSubCategory || selectedInventoryType || 'Inventario General';

        switch (currentView) {
            case 'dashboard':
                return <Dashboard items={items} movements={movements} />;
            case 'inventory':
                return <InventoryView items={filteredItems} openAddItemModal={() => setAddItemModalOpen(true)} onEditItem={openEditItemModal} onDeleteItem={handleDeleteItem} onItemHistory={openItemHistory} userRole={userRole} category={inventoryTitle} onGoBack={onGoBack} />;
            case 'movements':
                return <MovementsView movements={movements} items={items} personnel={personnel} openLogMovementModal={() => setLogMovementModalOpen(true)} onReturnLoan={handleReturnLoan} onGoBack={onGoBack} />;
            case 'purchaseOrders':
                return <PurchaseOrdersView purchaseOrders={purchaseOrders} items={items} openAddPurchaseOrderModal={() => setAddPOModalOpen(true)} onUpdateStatus={handleUpdatePOStatus} userRole={userRole} onGoBack={onGoBack} />;
            case 'personnel':
                return <PersonnelView personnel={personnel} openAddPersonnelModal={() => setAddPersonnelModalOpen(true)} onGoBack={onGoBack} onEditPersonnel={handleEditPersonnel} onDeletePersonnel={handleDeletePersonnel} userRole={userRole} />;
            case 'projects':
                return <ProjectsView projects={projects} movements={movements} items={items} personnel={personnel} onAddProject={handleAddProject} onGoBack={onGoBack} userRole={userRole} />;
            case 'loans':
                return <LoansView movements={movements} items={items} personnel={personnel} onReturnItem={handleReturnLoan} onGoBack={onGoBack} />;
            default:
                return <div>Seleccione una opción del menú lateral</div>;
        }
    };

    if (!isAuthenticated) return <LoginView onLoginSuccess={handleLogin} users={users} />;

    return (
        <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">
            {/* Mobile Sidebar Overlay */}
            {isSidebarOpen && <div onClick={() => setSidebarOpen(false)} className="fixed inset-0 bg-black/50 z-20 md:hidden" />}

            {/* Sidebar */}
            <aside className={`bg-white border-r border-gray-200 shadow-xl transition-all duration-300 ease-in-out fixed md:relative inset-y-0 left-0 z-30 transform md:transform-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:${isSidebarOpen ? 'w-64' : 'w-0 overflow-hidden'} flex flex-col`}>
                <div className="h-16 flex-shrink-0 flex items-center px-6 border-b bg-blue-700 text-white">
                    <h2 className="text-xl font-black tracking-tighter">BODEGA MAESTRA</h2>
                </div>

                <div className="flex-1 overflow-y-auto py-4 scrollbar-hide">
                    <nav className="px-2 space-y-1">
                        <NavItem icon={DashboardIcon} label="Tablero Principal" onClick={() => selectView('dashboard')} isActive={currentView === 'dashboard'} />

                        <NavHeader label="Operaciones de Obra" />
                        <NavItem icon={HardHatIcon} label="Proyectos y Gastos" onClick={() => selectView('projects')} isActive={currentView === 'projects'} />
                        <NavItem icon={ClockIcon} label="Préstamos Vigentes" onClick={() => selectView('loans')} isActive={currentView === 'loans'} />
                        <NavItem icon={MovementsIcon} label="Histórico Movimientos" onClick={() => selectView('movements')} isActive={currentView === 'movements'} />

                        <NavHeader label="Inventario por Categoría" />
                        <NavItem icon={HandToolIcon} label="Herramienta Manual" onClick={() => selectInventoryTypeFilter(InventoryType.HAND_TOOL)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.HAND_TOOL} />
                        <NavItem icon={ElectricalToolIcon} label="Herramienta Eléctrica" onClick={() => selectInventoryTypeFilter(InventoryType.ELECTRICAL_TOOL)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.ELECTRICAL_TOOL} />
                        <NavItem icon={PpeIcon} label="Seguridad (EPP)" onClick={() => selectInventoryTypeFilter(InventoryType.PPE)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.PPE} />
                        <NavItem icon={SingleUseIcon} label="Consumibles" onClick={() => selectInventoryTypeFilter(InventoryType.SINGLE_USE)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.SINGLE_USE} />

                        <NavHeader label="Administración Central" />
                        <NavItem icon={PurchaseOrdersIcon} label="Órdenes de Compra" onClick={() => selectView('purchaseOrders')} isActive={currentView === 'purchaseOrders'}/>
                        <NavItem icon={PersonnelIcon} label="Gestión de Personal" onClick={() => selectView('personnel')} isActive={currentView === 'personnel'} />

                        <div className="pt-8 px-2">
                             <button onClick={handleLogout} className="w-full flex items-center justify-center p-3 bg-red-100 text-red-700 rounded-xl hover:bg-red-200 transition-colors font-bold text-xs">
                                <LogOutIcon className="w-5 h-5 mr-2" />
                                CERRAR SESIÓN / CAMBIAR
                             </button>
                        </div>
                    </nav>
                </div>
            </aside>

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                <Header 
                    toggleSidebar={() => setSidebarOpen(!isSidebarOpen)} 
                    userRole={userRole} 
                    setUserRole={setUserRole} 
                    onExportData={handleExportData} 
                    onImportData={handleImportData} 
                    onResetData={handleResetData} 
                    onOpenUserManagement={() => setUserManagementOpen(true)} 
                    onLogout={handleLogout} 
                />
                <main className="flex-1 p-4 md:p-6 overflow-y-auto bg-gray-50">
                    <div className="max-w-7xl mx-auto">
                        {renderView()}
                    </div>
                </main>
            </div>

            {/* Modals */}
            <AddItemModal isOpen={isAddItemModalOpen} onClose={() => setAddItemModalOpen(false)} onAddItem={handleAddItem} userRole={userRole} />
            <EditItemModal isOpen={isEditModalOpen} onClose={() => setEditModalOpen(false)} onEditItem={handleEditItem} itemToEdit={itemToEdit} />
            <LogMovementModal isOpen={isLogMovementModalOpen} onClose={() => setLogMovementModalOpen(false)} onLogMovement={handleLogMovement} items={items} personnel={personnel} projects={projects} userRole={userRole} filterInventoryType={selectedInventoryType || undefined} />
            <AddPersonnelModal isOpen={isAddPersonnelModalOpen} onClose={() => setAddPersonnelModalOpen(false)} onAddPersonnel={handleAddPersonnel} />
            <AddPurchaseOrderModal isOpen={isAddPOModalOpen} onClose={() => setAddPOModalOpen(false)} onAddPurchaseOrder={handleAddPurchaseOrder} items={items} />
            <ItemHistoryModal isOpen={isHistoryModalOpen} onClose={() => setHistoryModalOpen(false)} item={itemForHistory} movements={movements} personnel={personnel} />
            <UserManagementModal isOpen={isUserManagementOpen} onClose={() => setUserManagementOpen(false)} users={users} onAddUser={handleAddUser} onDeleteUser={handleDeleteUser} onEditUser={handleEditUser} />
        </div>
    );
};

const NavItem: React.FC<{ icon: React.ElementType, label: string, onClick: () => void, isActive: boolean }> = ({ icon: Icon, label, onClick, isActive }) => (
    <button 
        onClick={onClick} 
        className={`w-full flex items-center text-left px-4 py-3 text-sm font-semibold rounded-xl transition-all duration-200 ${isActive ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-100 hover:text-gray-900'}`}
    >
        <Icon className={`w-5 h-5 mr-3 ${isActive ? 'text-white' : 'text-gray-400'}`} />
        {label}
    </button>
);

const NavHeader: React.FC<{label: string}> = ({label}) => (
    <h3 className="px-5 pt-6 pb-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">{label}</h3>
);

export default App;

import React, { useState, useMemo } from 'react';
import { Project, Movement, Item, UserRole, MovementType, Personnel } from '../types';
import { PlusIcon } from './icons/PlusIcon';
import { ArrowLeftIcon } from './icons/ArrowLeftIcon';
import { HardHatIcon } from './icons/HardHatIcon';

interface ProjectsViewProps {
    projects: Project[];
    movements: Movement[];
    items: Item[];
    personnel: Personnel[];
    onAddProject: (project: Omit<Project, 'id'>) => void;
    onGoBack: () => void;
    userRole: UserRole;
}

export const ProjectsView: React.FC<ProjectsViewProps> = ({ projects, movements, items, personnel, onAddProject, onGoBack, userRole }) => {
    const [isAdding, setIsAdding] = useState(false);
    const [newProjectName, setNewProjectName] = useState('');
    const [newProjectDesc, setNewProjectDesc] = useState('');
    const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

    // Calcular estadísticas por proyecto: materiales sacados y costo total
    const projectStats = useMemo(() => {
        return projects.map(project => {
            const projectMovements = movements.filter(m => 
                m.projectId === project.id && 
                (m.type === MovementType.CHECK_OUT || m.type === MovementType.WASTE)
            );

            const totalItemsCount = projectMovements.reduce((acc, m) => acc + m.quantity, 0);
            const totalProjectValue = projectMovements.reduce((acc, m) => {
                const item = items.find(i => i.id === m.itemId);
                return acc + (item ? item.price * m.quantity : 0);
            }, 0);

            return { ...project, totalItemsCount, totalProjectValue };
        });
    }, [projects, movements, items]);

    const selectedProject = useMemo(() => 
        projectStats.find(p => p.id === selectedProjectId), 
    [projectStats, selectedProjectId]);

    // Detalle exhaustivo de movimientos para el proyecto seleccionado
    const detailedMovements = useMemo(() => {
        if (!selectedProjectId) return [];
        return movements
            .filter(m => m.projectId === selectedProjectId && (m.type === MovementType.CHECK_OUT || m.type === MovementType.WASTE))
            .map(m => {
                const item = items.find(i => i.id === m.itemId);
                const person = personnel.find(p => p.id === m.personnelId);
                return {
                    ...m,
                    itemName: item?.name || 'Desconocido',
                    unitPrice: item?.price || 0,
                    totalCost: (item?.price || 0) * m.quantity,
                    personName: person?.name || 'Sin asignar'
                };
            })
            .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    }, [movements, items, personnel, selectedProjectId]);

    // Resumen agrupado por material para saber qué se ha llevado más
    const inventoryConsumption = useMemo(() => {
        const consumptionMap: { [key: string]: { name: string, quantity: number, cost: number } } = {};
        detailedMovements.forEach(m => {
            if (!consumptionMap[m.itemId]) {
                consumptionMap[m.itemId] = { name: m.itemName, quantity: 0, cost: 0 };
            }
            consumptionMap[m.itemId].quantity += m.quantity;
            consumptionMap[m.itemId].cost += m.totalCost;
        });
        return Object.values(consumptionMap).sort((a, b) => b.cost - a.cost);
    }, [detailedMovements]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newProjectName.trim()) return;
        onAddProject({ name: newProjectName.trim(), description: newProjectDesc.trim(), status: 'active' });
        setIsAdding(false);
        setNewProjectName('');
        setNewProjectDesc('');
    };

    // VISTA DETALLADA DE UN PROYECTO
    if (selectedProject) {
        return (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                <div className="bg-white p-6 rounded-2xl shadow-xl border-l-8 border-blue-600">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                        <div className="flex items-center">
                            <button onClick={() => setSelectedProjectId(null)} className="mr-4 p-2 rounded-full hover:bg-gray-100 transition-colors">
                                <ArrowLeftIcon className="w-7 h-7 text-gray-700" />
                            </button>
                            <div>
                                <h2 className="text-3xl font-black text-gray-900 uppercase tracking-tight">{selectedProject.name}</h2>
                                <p className="text-gray-500 font-medium">{selectedProject.description || 'Sin descripción de obra'}</p>
                            </div>
                        </div>
                        <div className="text-right bg-blue-50 p-4 rounded-xl border border-blue-100 min-w-[200px]">
                            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Inversión Total en Obra</p>
                            <p className="text-4xl font-black text-blue-700">${selectedProject.totalProjectValue.toLocaleString()}</p>
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Tabla de todos los retiros de material */}
                    <div className="lg:col-span-2 bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden">
                        <div className="p-4 bg-gray-50 border-b flex justify-between items-center">
                            <h3 className="font-bold text-gray-700 uppercase text-xs tracking-widest">Bitácora de Salidas y Gastos</h3>
                            <span className="bg-gray-200 text-gray-600 px-2 py-1 rounded text-[10px] font-bold">{detailedMovements.length} Registros</span>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="min-w-full divide-y divide-gray-100">
                                <thead className="bg-gray-50/50">
                                    <tr>
                                        <th className="px-4 py-3 text-left text-[10px] font-black text-gray-400 uppercase">Fecha / Personal</th>
                                        <th className="px-4 py-3 text-left text-[10px] font-black text-gray-400 uppercase">Material</th>
                                        <th className="px-4 py-3 text-center text-[10px] font-black text-gray-400 uppercase">Cantidad</th>
                                        <th className="px-4 py-3 text-right text-[10px] font-black text-gray-400 uppercase">Costo Total</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50">
                                    {detailedMovements.map(m => (
                                        <tr key={m.id} className="hover:bg-blue-50/30 transition-colors">
                                            <td className="px-4 py-3">
                                                <div className="text-[11px] font-bold text-gray-800">{new Date(m.timestamp).toLocaleDateString()}</div>
                                                <div className="text-[10px] text-gray-500 font-medium truncate w-32">{m.personName}</div>
                                            </td>
                                            <td className="px-4 py-3">
                                                <div className="text-sm font-bold text-gray-900">{m.itemName}</div>
                                                {m.isLoan && <span className="text-[9px] bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded font-black">PRÉSTAMO</span>}
                                            </td>
                                            <td className="px-4 py-3 text-center text-sm font-black text-gray-700">{m.quantity}</td>
                                            <td className="px-4 py-3 text-right">
                                                <div className="text-sm font-black text-blue-600">${m.totalCost.toLocaleString()}</div>
                                                <div className="text-[9px] text-gray-400">${m.unitPrice.toFixed(2)} p/u</div>
                                            </td>
                                        </tr>
                                    ))}
                                    {detailedMovements.length === 0 && (
                                        <tr><td colSpan={4} className="py-20 text-center text-gray-400 italic font-medium">No se registran gastos para esta obra aún.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>

                    {/* Resumen Agrupado de Insumos */}
                    <div className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden h-fit">
                        <div className="p-4 bg-gray-50 border-b">
                            <h3 className="font-bold text-gray-700 uppercase text-xs tracking-widest">Resumen de Insumos</h3>
                        </div>
                        <div className="p-4 space-y-4">
                            {inventoryConsumption.map(mat => (
                                <div key={mat.name} className="flex flex-col space-y-1">
                                    <div className="flex justify-between items-start">
                                        <span className="text-sm font-bold text-gray-800 truncate w-40">{mat.name}</span>
                                        <span className="text-sm font-black text-blue-600">${mat.cost.toLocaleString()}</span>
                                    </div>
                                    <div className="flex justify-between items-center text-[10px] text-gray-500 font-medium uppercase">
                                        <span>Consumido: {mat.quantity} unidades</span>
                                        <span>{( (mat.cost / (selectedProject.totalProjectValue || 1)) * 100).toFixed(1)}%</span>
                                    </div>
                                    <div className="w-full bg-gray-100 h-1.5 rounded-full overflow-hidden">
                                        <div 
                                            className="bg-blue-500 h-full rounded-full" 
                                            style={{ width: `${Math.min((mat.cost / (selectedProject.totalProjectValue || 1)) * 100, 100)}%` }}
                                        ></div>
                                    </div>
                                </div>
                            ))}
                            {inventoryConsumption.length === 0 && (
                                <p className="text-center py-10 text-gray-400 text-sm">Sin datos para resumir.</p>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    // VISTA GENERAL DE TODOS LOS PROYECTOS
    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl shadow-md border border-gray-100 flex flex-col md:flex-row justify-between items-start md:items-center">
                 <div className="flex items-center mb-4 md:mb-0">
                    <button onClick={onGoBack} className="mr-4 p-2 rounded-full hover:bg-gray-100 transition-colors">
                        <ArrowLeftIcon className="w-6 h-6 text-gray-600" />
                    </button>
                    <div>
                        <h2 className="text-2xl font-black text-gray-800 flex items-center tracking-tighter">
                            <HardHatIcon className="w-8 h-8 mr-2 text-yellow-500"/>
                            CONTROL DE OBRAS Y PROYECTOS
                        </h2>
                        <p className="text-sm text-gray-500 font-bold uppercase tracking-wider text-[10px]">Gestión centralizada de costos y materiales</p>
                    </div>
                </div>
                {userRole === UserRole.OWNER && !isAdding && (
                    <button onClick={() => setIsAdding(true)} className="flex items-center bg-blue-600 hover:bg-blue-700 text-white font-black py-3 px-6 rounded-xl shadow-lg transition-transform hover:scale-105 uppercase text-xs tracking-widest">
                        <PlusIcon className="w-5 h-5 mr-2" />
                        Añadir Nueva Obra
                    </button>
                )}
            </div>

            {isAdding && (
                <div className="bg-white p-6 rounded-2xl shadow-xl border-2 border-blue-500 animate-in slide-in-from-top duration-300">
                    <h3 className="font-black text-gray-800 mb-4 text-xl uppercase tracking-tighter">Registrar Nuevo Proyecto</h3>
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Nombre de la Obra</label>
                                <input
                                    type="text"
                                    placeholder="Ej: Torre Residencial Alameda"
                                    value={newProjectName}
                                    onChange={e => setNewProjectName(e.target.value)}
                                    className="w-full p-3 border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold text-gray-700"
                                    required
                                />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Descripción / Ubicación</label>
                                <input
                                    type="text"
                                    placeholder="Ej: Calle 10 con Carrera 5"
                                    value={newProjectDesc}
                                    onChange={e => setNewProjectDesc(e.target.value)}
                                    className="w-full p-3 border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold text-gray-700"
                                />
                            </div>
                        </div>
                        <div className="flex justify-end space-x-2">
                            <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-2 text-gray-500 font-bold hover:bg-gray-100 rounded-xl uppercase text-xs">Descartar</button>
                            <button type="submit" className="px-6 py-2 bg-blue-600 text-white font-black rounded-xl hover:bg-blue-700 uppercase text-xs tracking-widest shadow-md">Crear Obra</button>
                        </div>
                    </form>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {projectStats.map(project => (
                    <div 
                        key={project.id} 
                        onClick={() => setSelectedProjectId(project.id)}
                        className="group bg-white border border-gray-100 rounded-3xl p-6 hover:border-blue-500 hover:shadow-2xl transition-all cursor-pointer relative overflow-hidden flex flex-col justify-between"
                    >
                        <div className="absolute top-0 right-0 p-4">
                            <span className="bg-green-100 text-green-700 text-[9px] font-black px-2 py-0.5 rounded-full uppercase">ACTIVO</span>
                        </div>
                        <div>
                            <h3 className="font-black text-xl text-gray-900 group-hover:text-blue-600 transition-colors uppercase leading-tight mb-1 pr-12">{project.name}</h3>
                            <p className="text-xs text-gray-500 font-bold mb-6 h-10 line-clamp-2 uppercase tracking-wide opacity-80">{project.description || 'SIN DESCRIPCIÓN'}</p>
                        </div>

                        <div className="space-y-3 pt-4 border-t border-gray-50">
                            <div className="flex justify-between items-end">
                                <span className="text-[10px] text-gray-400 font-black uppercase">Materiales Salidos</span>
                                <span className="font-black text-gray-800 text-lg">{project.totalItemsCount}</span>
                            </div>
                            <div className="flex justify-between items-end">
                                <span className="text-[10px] text-gray-400 font-black uppercase">Gasto Acumulado</span>
                                <span className="font-black text-2xl text-blue-600">${project.totalProjectValue.toLocaleString()}</span>
                            </div>
                        </div>

                        <div className="mt-6 w-full py-3 bg-gray-50 group-hover:bg-blue-600 text-gray-400 group-hover:text-white rounded-2xl text-center text-[10px] font-black transition-all uppercase tracking-widest">
                            ENTRAR A DESGLOSE DE GASTOS →
                        </div>
                    </div>
                ))}
            </div>

            {projects.length === 0 && (
                <div className="text-center py-24 bg-white rounded-3xl border-2 border-dashed border-gray-200">
                    <HardHatIcon className="w-20 h-20 mx-auto mb-4 opacity-10 text-gray-900"/>
                    <p className="text-xl font-bold text-gray-400 uppercase tracking-tighter">No hay obras registradas en el sistema todavía.</p>
                </div>
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { AppUser, UserRole } from '../types';
import { XIcon } from './icons/XIcon';
import { TrashIcon } from './icons/TrashIcon';
import { EditIcon } from './icons/EditIcon';

interface UserManagementModalProps {
    isOpen: boolean;
    onClose: () => void;
    users: AppUser[];
    onAddUser: (user: AppUser) => void;
    onDeleteUser: (id: string) => void;
    onEditUser: (user: AppUser) => void;
}

export const UserManagementModal: React.FC<UserManagementModalProps> = ({ isOpen, onClose, users, onAddUser, onDeleteUser, onEditUser }) => {
    const [newUsername, setNewUsername] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [newName, setNewName] = useState('');
    const [newRole, setNewRole] = useState<UserRole>(UserRole.EMPLOYEE);
    const [editingUserId, setEditingUserId] = useState<string | null>(null);

    if (!isOpen) return null;

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!newUsername.trim() || !newPassword.trim() || !newName.trim()) {
            alert("Todos los campos son obligatorios para crear un acceso.");
            return;
        }

        if (!editingUserId && users.some(u => u.username === newUsername)) {
            alert("El nombre de usuario ya está ocupado. Intente con otro.");
            return;
        }

        if (editingUserId) {
            const updatedUser: AppUser = {
                id: editingUserId,
                username: newUsername.trim(),
                password: newPassword,
                name: newName.trim(),
                role: newRole
            };
            onEditUser(updatedUser);
            setEditingUserId(null);
        } else {
            const newUser: AppUser = {
                id: `user-${Date.now()}`,
                username: newUsername.trim(),
                password: newPassword,
                name: newName.trim(),
                role: newRole
            };
            onAddUser(newUser);
        }

        setNewUsername('');
        setNewPassword('');
        setNewName('');
        setNewRole(UserRole.EMPLOYEE);
    };

    const handleEditClick = (user: AppUser) => {
        setEditingUserId(user.id);
        setNewUsername(user.username);
        setNewPassword(user.password);
        setNewName(user.name);
        setNewRole(user.role);
    };

    const handleCancelEdit = () => {
        setEditingUserId(null);
        setNewUsername('');
        setNewPassword('');
        setNewName('');
        setNewRole(UserRole.EMPLOYEE);
    };

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex justify-center items-center z-50">
            <div className="bg-white rounded-3xl shadow-2xl p-8 w-full max-w-4xl m-4 max-h-[90vh] overflow-hidden flex flex-col border border-gray-100">
                <div className="flex justify-between items-center mb-8">
                    <div>
                        <h2 className="text-3xl font-black text-gray-900 tracking-tighter uppercase">Gestión de Accesos</h2>
                        <p className="text-xs text-gray-500 font-bold uppercase tracking-widest">Configuración de Usuarios y Permisos</p>
                    </div>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full text-gray-400 hover:text-gray-600 transition-colors">
                        <XIcon className="w-6 h-6" />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto grid grid-cols-1 lg:grid-cols-2 gap-10">
                    {/* Formulario */}
                    <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100 h-fit">
                        <h3 className="font-black text-xs mb-6 text-blue-600 uppercase tracking-widest border-b pb-2">
                            {editingUserId ? 'ACTUALIZAR DATOS DE ACCESO' : 'REGISTRAR NUEVO ACCESO'}
                        </h3>
                        <form onSubmit={handleSubmit} className="space-y-5">
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Nombre Real Completo</label>
                                <input
                                    type="text"
                                    value={newName}
                                    onChange={e => setNewName(e.target.value)}
                                    placeholder="Ej: Andres Felipe"
                                    className="w-full p-3 bg-white border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold text-gray-700 transition-colors"
                                    required
                                />
                            </div>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div>
                                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Usuario Login</label>
                                    <input
                                        type="text"
                                        value={newUsername}
                                        onChange={e => setNewUsername(e.target.value)}
                                        placeholder="ej: andres_bodega"
                                        className="w-full p-3 bg-white border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold text-gray-700 transition-colors"
                                        required
                                    />
                                </div>
                                <div>
                                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Contraseña</label>
                                    <input
                                        type="password"
                                        value={newPassword}
                                        onChange={e => setNewPassword(e.target.value)}
                                        placeholder="••••••••"
                                        className="w-full p-3 bg-white border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold text-gray-700 transition-colors"
                                        required
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Nivel de Seguridad</label>
                                <select 
                                    value={newRole}
                                    onChange={e => setNewRole(e.target.value as UserRole)}
                                    className="w-full p-3 bg-white border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-bold text-gray-700 transition-colors cursor-pointer"
                                >
                                    <option value={UserRole.EMPLOYEE}>Bodeguero / Operativo</option>
                                    <option value={UserRole.OWNER}>Administrador Supremo</option>
                                </select>
                            </div>

                            <div className="flex space-x-3 pt-4">
                                {editingUserId && (
                                    <button type="button" onClick={handleCancelEdit} className="flex-1 bg-gray-200 text-gray-600 py-3 rounded-xl hover:bg-gray-300 font-black uppercase text-xs transition-all">
                                        Cancelar
                                    </button>
                                )}
                                <button type="submit" className="flex-1 bg-blue-600 text-white py-3 rounded-xl hover:bg-blue-700 font-black uppercase text-xs shadow-lg transition-all transform hover:scale-[1.02]">
                                    {editingUserId ? 'GUARDAR CAMBIOS' : 'CREAR ACCESO'}
                                </button>
                            </div>
                        </form>
                    </div>

                    {/* Lista de Usuarios */}
                    <div className="space-y-4 h-fit">
                        <h3 className="font-black text-[10px] text-gray-400 uppercase tracking-widest px-2">Usuarios con Acceso Autorizado</h3>
                        <div className="space-y-3">
                            {users.map(user => (
                                <div key={user.id} className={`group flex justify-between items-center border-2 p-4 rounded-3xl transition-all ${editingUserId === user.id ? 'bg-blue-50 border-blue-200' : 'bg-white border-gray-100 hover:border-gray-300'}`}>
                                    <div className="flex items-center space-x-4">
                                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg ${user.role === UserRole.OWNER ? 'bg-indigo-100 text-indigo-600' : 'bg-blue-100 text-blue-600'}`}>
                                            {user.username.charAt(0).toUpperCase()}
                                        </div>
                                        <div>
                                            <p className="font-black text-gray-900 uppercase text-xs tracking-tighter">{user.name}</p>
                                            <p className="text-[10px] text-gray-400 font-bold tracking-widest lowercase">@{user.username}</p>
                                            <span className={`text-[9px] font-black px-2 py-0.5 rounded-full uppercase inline-block mt-1 ${user.role === UserRole.OWNER ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-500'}`}>
                                                {user.role === UserRole.OWNER ? 'Admin Supremo' : 'Bodeguero'}
                                            </span>
                                        </div>
                                    </div>
                                    <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button 
                                            onClick={() => handleEditClick(user)}
                                            className="p-2 text-blue-500 hover:bg-blue-100 rounded-full transition-colors"
                                            title="Editar Acceso"
                                        >
                                            <EditIcon className="w-5 h-5"/>
                                        </button>
                                        {/* El usuario juli es el maestro y no se puede borrar */}
                                        {user.username !== 'juli' && (
                                            <button 
                                                onClick={() => {
                                                    if(window.confirm(`¿Seguro que desea ELIMINAR el acceso de "${user.name}"?`)) onDeleteUser(user.id);
                                                }}
                                                className="p-2 text-red-500 hover:bg-red-100 rounded-full transition-colors"
                                                title="Eliminar Acceso"
                                            >
                                                <TrashIcon className="w-5 h-5"/>
                                            </button>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                        {users.length === 0 && <p className="text-center py-10 text-gray-400 font-bold uppercase text-xs italic">No hay usuarios configurados.</p>}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React from 'react';

export const LogOutIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" {...props}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 9V5.25A2.25 2.25 0 0013.5 3h-6a2.25 2.25 0 00-2.25 2.25v13.5A2.25 2.25 0 007.5 21h6a2.25 2.25 0 002.25-2.25V15M12 9l-3 3m0 0l3 3m-3-3h12.75" />
    </svg>
);

import React, { useState, useMemo, useEffect } from 'react';
import { AddItemModal } from './components/AddItemModal';
import { EditItemModal } from './components/EditItemModal';
import { Dashboard } from './components/Dashboard';
import { Header } from './components/Header';
import { InventoryView } from './components/InventoryView';
import { LogMovementModal } from './components/LogMovementModal';
import { MovementsView } from './components/MovementsView';
import { AddPersonnelModal } from './components/AddPersonnelModal';
import { PersonnelView } from './components/PersonnelView';
import { AddPurchaseOrderModal } from './components/AddPurchaseOrderModal';
import { PurchaseOrdersView } from './components/PurchaseOrdersView';
import { ProjectsView } from './components/ProjectsView';
import { LoansView } from './components/LoansView';
import { ItemHistoryModal } from './components/ItemHistoryModal';
import { UserManagementModal } from './components/UserManagementModal';

import { mockItems, mockMovements, mockPersonnel, mockPurchaseOrders, mockProjects, mockUsers } from './mockData';
import { Item, Movement, MovementType, Personnel, PurchaseOrder, PurchaseOrderStatus, UserRole, InventoryType, Project, AppUser } from './types';
import { LoginView } from './components/LoginView';

// Icons for Sidebar
import { DashboardIcon } from './components/icons/DashboardIcon';
import { InventoryIcon } from './components/icons/InventoryIcon';
import { MovementsIcon } from './components/icons/MovementsIcon';
import { PersonnelIcon } from './components/icons/PersonnelIcon';
import { PurchaseOrdersIcon } from './components/icons/PurchaseOrdersIcon';
import { HandToolIcon } from './components/icons/HandToolIcon';
import { ElectricalToolIcon } from './components/icons/ElectricalToolIcon';
import { PpeIcon } from './components/icons/PpeIcon';
import { SingleUseIcon } from './components/icons/SingleUseIcon';
import { HardHatIcon } from './components/icons/HardHatIcon';
import { ClockIcon } from './components/icons/ClockIcon';
import { LogOutIcon } from './components/icons/LogOutIcon';

type View = 'dashboard' | 'inventory' | 'movements' | 'purchaseOrders' | 'personnel' | 'projects' | 'loans';

const App: React.FC = () => {
    // State Management
    const [isAuthenticated, setIsAuthenticated] = useState(false);

    // Users Management State
    const [users, setUsers] = useState<AppUser[]>(() => {
        try {
            const savedUsers = localStorage.getItem('inventory_users');
            return savedUsers ? JSON.parse(savedUsers) : mockUsers;
        } catch (e) {
            console.error("Failed to parse users", e);
            return mockUsers;
        }
    });

    const [items, setItems] = useState<Item[]>(() => {
        try {
            const savedItems = localStorage.getItem('inventory_items');
            return savedItems ? JSON.parse(savedItems) : mockItems;
        } catch (e) {
            console.error("Failed to parse items", e);
            return mockItems;
        }
    });

    const [movements, setMovements] = useState<Movement[]>(() => {
        try {
            const savedMovements = localStorage.getItem('inventory_movements');
            if (savedMovements) {
                return JSON.parse(savedMovements).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) }));
            }
            return mockMovements;
        } catch (e) {
            console.error("Failed to parse movements", e);
            return mockMovements;
        }
    });

    const [personnel, setPersonnel] = useState<Personnel[]>(() => {
        try {
            const savedPersonnel = localStorage.getItem('inventory_personnel');
            return savedPersonnel ? JSON.parse(savedPersonnel) : mockPersonnel;
        } catch (e) {
            console.error("Failed to parse personnel", e);
            return mockPersonnel;
        }
    });

    const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>(() => {
        try {
            const savedPOs = localStorage.getItem('inventory_purchase_orders');
            if (savedPOs) {
                return JSON.parse(savedPOs).map((po: any) => ({
                    ...po,
                    orderDate: new Date(po.orderDate),
                    expectedDeliveryDate: po.expectedDeliveryDate ? new Date(po.expectedDeliveryDate) : undefined,
                    receivedDate: po.receivedDate ? new Date(po.receivedDate) : undefined,
                }));
            }
            return mockPurchaseOrders;
        } catch (e) {
            console.error("Failed to parse purchase orders", e);
            return mockPurchaseOrders;
        }
    });

    const [projects, setProjects] = useState<Project[]>(() => {
        try {
            const savedProjects = localStorage.getItem('inventory_projects');
            return savedProjects ? JSON.parse(savedProjects) : mockProjects;
        } catch (e) {
            console.error("Failed to parse projects", e);
            return mockProjects;
        }
    });

    const [userRole, setUserRole] = useState<UserRole>(UserRole.OWNER);

    // Persist Data Hooks
    useEffect(() => {
        localStorage.setItem('inventory_users', JSON.stringify(users));
    }, [users]);
    useEffect(() => {
        localStorage.setItem('inventory_items', JSON.stringify(items));
    }, [items]);
    useEffect(() => {
        localStorage.setItem('inventory_movements', JSON.stringify(movements));
    }, [movements]);
    useEffect(() => {
        localStorage.setItem('inventory_personnel', JSON.stringify(personnel));
    }, [personnel]);
    useEffect(() => {
        localStorage.setItem('inventory_purchase_orders', JSON.stringify(purchaseOrders));
    }, [purchaseOrders]);
    useEffect(() => {
        localStorage.setItem('inventory_projects', JSON.stringify(projects));
    }, [projects]);


    // UI State
    const [currentView, setCurrentView] = useState<View>('dashboard');
    const [selectedSubCategory, setSelectedSubCategory] = useState<string | null>(null);
    const [selectedInventoryType, setSelectedInventoryType] = useState<InventoryType | null>(null);
    const [isSidebarOpen, setSidebarOpen] = useState(true);

    // Modal State
    const [isAddItemModalOpen, setAddItemModalOpen] = useState(false);
    const [isEditModalOpen, setEditModalOpen] = useState(false);
    const [itemToEdit, setItemToEdit] = useState<Item | null>(null);
    const [isLogMovementModalOpen, setLogMovementModalOpen] = useState(false);
    const [isAddPersonnelModalOpen, setAddPersonnelModalOpen] = useState(false);
    const [isAddPOModalOpen, setAddPOModalOpen] = useState(false);
    const [isUserManagementOpen, setUserManagementOpen] = useState(false);

    // Kardex State
    const [itemForHistory, setItemForHistory] = useState<Item | null>(null);
    const [isHistoryModalOpen, setHistoryModalOpen] = useState(false);

    const uniqueSubCategories = useMemo(() => {
        const subCategories = new Set(items.map(item => item.subCategory));
        return Array.from(subCategories).sort();
    }, [items]);

    // Handlers
    const handleLogin = (role: UserRole) => {
        setUserRole(role);
        setIsAuthenticated(true);
    }

    const handleLogout = () => {
        if (window.confirm('¿Desea cerrar sesión para cambiar de usuario?')) {
            setIsAuthenticated(false);
            setCurrentView('dashboard');
        }
    }

    const handleAddUser = (newUser: AppUser) => {
        setUsers([...users, newUser]);
    }
    const handleEditUser = (updatedUser: AppUser) => {
        setUsers(users.map(u => u.id === updatedUser.id ? updatedUser : u));
    }
    const handleDeleteUser = (id: string) => {
        setUsers(users.filter(u => u.id !== id));
    }

    const handleAddItem = (item: Omit<Item, 'id'>) => {
        const newItem: Item = { ...item, id: `item-${Date.now()}` };
        setItems(prev => [...prev, newItem]);
    };

    const handleEditItem = (updatedItem: Item) => {
        setItems(prev => prev.map(item => item.id === updatedItem.id ? updatedItem : item));
        setItemToEdit(null);
    };

    const handleDeleteItem = (itemId: string) => {
        if (window.confirm('¿Está seguro de que desea eliminar este artículo?')) {
            setItems(prev => prev.filter(item => item.id !== itemId));
        }
    };

    const openEditItemModal = (item: Item) => {
        setItemToEdit(item);
        setEditModalOpen(true);
    };

    const openItemHistory = (item: Item) => {
        setItemForHistory(item);
        setHistoryModalOpen(true);
    };

    const handleLogMovement = (movement: Omit<Movement, 'id' | 'timestamp'>) => {
        const newMovement: Movement = { 
            ...movement, 
            id: `move-${Date.now()}`, 
            timestamp: new Date(),
            isReturned: false 
        };
        setMovements(prev => [newMovement, ...prev]);

        const item = items.find(i => i.id === movement.itemId);
        if (item) {
            let newQuantity = item.quantity;
            if (movement.type === MovementType.CHECK_OUT || movement.type === MovementType.WASTE) {
                newQuantity -= movement.quantity;
            } else {
                newQuantity += movement.quantity;
            }
            handleEditItem({ ...item, quantity: newQuantity });
        }
    };

    const handleReturnLoan = (movementId: string) => {
        const movement = movements.find(m => m.id === movementId);
        if (!movement || movement.isReturned) return;

        const itemName = items.find(i => i.id === movement.itemId)?.name || 'artículo';
        if (window.confirm(`¿Confirmar devolución de: ${itemName}?`)) {
            setMovements(prev => prev.map(m => m.id === movementId ? { ...m, isReturned: true } : m));
            const item = items.find(i => i.id === movement.itemId);
            if (item) {
                handleEditItem({ ...item, quantity: item.quantity + movement.quantity });
            }
        }
    };

    const handleAddPersonnel = (person: Omit<Personnel, 'id'>) => {
        const newPerson: Personnel = { ...person, id: `person-${Date.now()}` };
        setPersonnel(prev => [...prev, newPerson]);
    };

    const handleEditPersonnel = (updatedPerson: Personnel) => {
        setPersonnel(prev => prev.map(p => p.id === updatedPerson.id ? updatedPerson : p));
    };

    const handleDeletePersonnel = (id: string) => {
        if (window.confirm('¿Eliminar a esta persona del sistema?')) {
            setPersonnel(prev => prev.filter(p => p.id !== id));
        }
    };

    const handleAddProject = (project: Omit<Project, 'id'>) => {
        const newProject: Project = { ...project, id: `proj-${Date.now()}` };
        setProjects(prev => [...prev, newProject]);
    };

    const handleAddPurchaseOrder = (order: Omit<PurchaseOrder, 'id'>) => {
        const newOrder: PurchaseOrder = { ...order, id: `po-${Date.now()}` };
        setPurchaseOrders(prev => [newOrder, ...prev]);
    };

    const handleUpdatePOStatus = (orderId: string, status: PurchaseOrderStatus) => {
        setPurchaseOrders(prev => prev.map(order => {
            if (order.id === orderId) {
                const updatedOrder = { ...order, status };
                if (status === PurchaseOrderStatus.RECEIVED) {
                    updatedOrder.receivedDate = new Date();
                    updatedOrder.items.forEach(orderItem => {
                        handleLogMovement({
                            itemId: orderItem.itemId,
                            type: MovementType.PURCHASE,
                            quantity: orderItem.quantity,
                            notes: `Recibido de orden de compra #${order.id.split('-')[1]}`
                        });
                    });
                }
                return updatedOrder;
            }
            return order;
        }));
    };

    const handleExportData = () => {
        const data = { 
            items, 
            movements, 
            personnel, 
            purchaseOrders, 
            projects, 
            users, 
            version: "2.0",
            exportDate: new Date().toISOString() 
        };
        const dataStr = JSON.stringify(data, null, 2);
        const blob = new Blob([dataStr], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `backup_bodega_cop_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleImportData = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const json = e.target?.result as string;
                const data = JSON.parse(json);

                // Validación estricta para asegurar que el backup sea compatible
                if (data.items && data.movements && data.personnel && data.projects) {
                    if (window.confirm('¡ATENCIÓN! Se reemplazarán todos los datos por el respaldo. ¿Confirmar restauración?')) {
                        // Limpiar y guardar
                        localStorage.clear();
                        localStorage.setItem('inventory_items', JSON.stringify(data.items));
                        localStorage.setItem('inventory_movements', JSON.stringify(data.movements));
                        localStorage.setItem('inventory_personnel', JSON.stringify(data.personnel));
                        localStorage.setItem('inventory_projects', JSON.stringify(data.projects));
                        if (data.purchaseOrders) localStorage.setItem('inventory_purchase_orders', JSON.stringify(data.purchaseOrders));
                        if (data.users) localStorage.setItem('inventory_users', JSON.stringify(data.users));

                        alert('Restauración completada. El sistema se reiniciará para aplicar los cambios.');
                        window.location.reload();
                    }
                } else {
                    alert('Error: El archivo de backup no es válido o está incompleto.');
                }
            } catch (error) {
                console.error("Error importing data", error);
                alert('Error al leer el archivo. Asegúrese de que sea un JSON válido.');
            }
        };
        reader.readAsText(file);
        event.target.value = '';
    };

    const handleResetData = () => {
        const password = prompt("ADVERTENCIA: Se borrará TODO.\nIngrese la CLAVE MAESTRA para confirmar:");
        if (password === '00') {
            if (window.confirm('¿Está absolutamente seguro de borrar la base de datos?')) {
                localStorage.clear();
                window.location.reload();
            }
        } else if (password !== null) {
            alert("Clave incorrecta.");
        }
    };

    const selectView = (view: View) => {
        setCurrentView(view);
        setSelectedSubCategory(null);
        setSelectedInventoryType(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    const selectInventoryTypeFilter = (type: InventoryType) => {
        setCurrentView('inventory');
        setSelectedInventoryType(type);
        setSelectedSubCategory(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    const selectInventorySubCategory = (subCategory: string | null) => {
        setCurrentView('inventory');
        setSelectedSubCategory(subCategory);
        if (subCategory === null) setSelectedInventoryType(null);
        if (window.innerWidth < 768) setSidebarOpen(false);
    }

    if (!isAuthenticated) return <LoginView onLoginSuccess={handleLogin} users={users} />;

    return (
        <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">
            {isSidebarOpen && <div onClick={() => setSidebarOpen(false)} className="fixed inset-0 bg-black/50 z-20 md:hidden" />}

            <aside className={`bg-white border-r border-gray-200 shadow-xl transition-all duration-300 ease-in-out fixed md:relative inset-y-0 left-0 z-30 transform md:transform-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:${isSidebarOpen ? 'w-64' : 'w-0 overflow-hidden'} flex flex-col`}>
                <div className="h-16 flex-shrink-0 flex items-center px-6 border-b bg-blue-700 text-white">
                    <h2 className="text-xl font-black tracking-tighter uppercase">Bodega Maestra</h2>
                </div>

                <div className="flex-1 overflow-y-auto py-4 scrollbar-hide">
                    <nav className="px-2 space-y-1">
                        <NavItem icon={DashboardIcon} label="Tablero Principal" onClick={() => selectView('dashboard')} isActive={currentView === 'dashboard'} />
                        <NavHeader label="Proyectos" />
                        <NavItem icon={HardHatIcon} label="Obras y Gastos" onClick={() => selectView('projects')} isActive={currentView === 'projects'} />
                        <NavItem icon={ClockIcon} label="Herramienta en Préstamo" onClick={() => selectView('loans')} isActive={currentView === 'loans'} />
                        <NavItem icon={MovementsIcon} label="Kardex General" onClick={() => selectView('movements')} isActive={currentView === 'movements'} />

                        <NavHeader label="Inventario" />
                        <NavItem icon={HandToolIcon} label="Herramienta Manual" onClick={() => selectInventoryTypeFilter(InventoryType.HAND_TOOL)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.HAND_TOOL} />
                        <NavItem icon={ElectricalToolIcon} label="Herramienta Eléctrica" onClick={() => selectInventoryTypeFilter(InventoryType.ELECTRICAL_TOOL)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.ELECTRICAL_TOOL} />
                        <NavItem icon={PpeIcon} label="Indumentaria (EPP)" onClick={() => selectInventoryTypeFilter(InventoryType.PPE)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.PPE} />
                        <NavItem icon={SingleUseIcon} label="Material de Consumo" onClick={() => selectInventoryTypeFilter(InventoryType.SINGLE_USE)} isActive={currentView === 'inventory' && selectedInventoryType === InventoryType.SINGLE_USE} />

                        <NavHeader label="Empresa" />
                        <NavItem icon={PurchaseOrdersIcon} label="Órdenes de Compra" onClick={() => selectView('purchaseOrders')} isActive={currentView === 'purchaseOrders'}/>
                        <NavItem icon={PersonnelIcon} label="Personal" onClick={() => selectView('personnel')} isActive={currentView === 'personnel'} />

                        <div className="pt-8 px-2">
                             <button onClick={handleLogout} className="w-full flex items-center justify-center p-3 bg-red-100 text-red-700 rounded-xl hover:bg-red-200 transition-colors font-bold text-xs">
                                <LogOutIcon className="w-5 h-5 mr-2" />
                                SALIR DEL SISTEMA
                             </button>
                        </div>
                    </nav>
                </div>
            </aside>

            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                <Header toggleSidebar={() => setSidebarOpen(!isSidebarOpen)} userRole={userRole} setUserRole={setUserRole} onExportData={handleExportData} onImportData={handleImportData} onResetData={handleResetData} onOpenUserManagement={() => setUserManagementOpen(true)} onLogout={handleLogout} />
                <main className="flex-1 p-4 md:p-6 overflow-y-auto bg-gray-50">
                    <div className="max-w-7xl mx-auto">
                        {currentView === 'dashboard' && <Dashboard items={items} movements={movements} />}
                        {currentView === 'inventory' && <InventoryView items={filteredItems} openAddItemModal={() => setAddItemModalOpen(true)} onEditItem={openEditItemModal} onDeleteItem={handleDeleteItem} onItemHistory={openItemHistory} userRole={userRole} category={selectedSubCategory || selectedInventoryType || 'Todos'} onGoBack={() => selectView('dashboard')} />}
                        {currentView === 'movements' && <MovementsView movements={movements} items={items} personnel={personnel} openLogMovementModal={() => setLogMovementModalOpen(true)} onReturnLoan={handleReturnLoan} onGoBack={() => selectView('dashboard')} />}
                        {currentView === 'purchaseOrders' && <PurchaseOrdersView purchaseOrders={purchaseOrders} items={items} openAddPurchaseOrderModal={() => setAddPOModalOpen(true)} onUpdateStatus={handleUpdatePOStatus} userRole={userRole} onGoBack={() => selectView('dashboard')} />}
                        {currentView === 'personnel' && <PersonnelView personnel={personnel} openAddPersonnelModal={() => setAddPersonnelModalOpen(true)} onGoBack={() => selectView('dashboard')} onEditPersonnel={handleEditPersonnel} onDeletePersonnel={handleDeletePersonnel} userRole={userRole} />}
                        {currentView === 'projects' && <ProjectsView projects={projects} movements={movements} items={items} personnel={personnel} onAddProject={handleAddProject} onGoBack={() => selectView('dashboard')} userRole={userRole} />}
                        {currentView === 'loans' && <LoansView movements={movements} items={items} personnel={personnel} onReturnItem={handleReturnLoan} onGoBack={() => selectView('dashboard')} />}
                    </div>
                </main>
            </div>

            <AddItemModal isOpen={isAddItemModalOpen} onClose={() => setAddItemModalOpen(false)} onAddItem={handleAddItem} userRole={userRole} />
            <EditItemModal isOpen={isEditModalOpen} onClose={() => setEditModalOpen(false)} onEditItem={handleEditItem} itemToEdit={itemToEdit} />
            <LogMovementModal isOpen={isLogMovementModalOpen} onClose={() => setLogMovementModalOpen(false)} onLogMovement={handleLogMovement} items={items} personnel={personnel} projects={projects} userRole={userRole} filterInventoryType={selectedInventoryType || undefined} />
            <AddPersonnelModal isOpen={isAddPersonnelModalOpen} onClose={() => setAddPersonnelModalOpen(false)} onAddPersonnel={handleAddPersonnel} />
            <AddPurchaseOrderModal isOpen={isAddPOModalOpen} onClose={() => setAddPOModalOpen(false)} onAddPurchaseOrder={handleAddPurchaseOrder} items={items} />
